window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["24695868"]={"book":{"id":24695868,"title":"行之有效的正面管教工具","author":"甄颖","translator":"","publisher":"广东教育出版社","pubdate":"2013-6-1","isbn":"9787554802533","tags":["育儿","正面管教","家庭教育","教育","行之有效的正面管教工具","心理学","案例","育儿必读"],"memCount":18},"np":1,"pb":[19],"idx":[{"i":8669,"t":"带孩子做一次选择轮","l":"TF2-1","c":"陈丽青","g":1,"p":1},{"i":3832,"t":" 如何鼓励孩子，让他成为一个自信的人？","l":"TF1-1","c":"王文婷","g":0,"p":1},{"i":3580,"t":" 当身边的人出现负面情绪时，如何利用“共情”和他们建立连接？","l":"TF1-2","c":"王文婷","g":1,"p":1},{"i":3533,"t":"鼓励和赞美","l":"TF2-3","c":"金凤","g":1,"p":1},{"i":3491,"t":"如何教会孩子将日常的行为习惯制作成惯例表？","l":"TF2-2","c":"金凤","g":1,"p":1},{"i":3241,"t":"用拥抱来解决各项冲突","l":"TF1-2","c":"素颜","g":0,"p":1},{"i":3082,"t":"鼓励VS赞美","l":"TF2-3","c":"金凤","g":1,"p":1},{"i":3081,"t":"如何正面引导孩子应对负面情绪以及解决问题？","l":"TF2-4","c":"金凤","g":1,"p":1},{"i":3079,"t":"如何引导教育孩子，让孩子学会自主？","l":"TF2-2","c":"金凤","g":1,"p":1},{"i":3078,"t":"如何正面引导孩子以达到教育孩子目的？","l":"TF1-2","c":"金凤","g":1,"p":1},{"i":3077,"t":"如何使用启发式提问技巧教育孩子？","l":"TF2-1","c":"金凤","g":0,"p":1},{"i":3076,"t":"如何使用启发式提问技巧？","l":"TF2-1","c":"金凤","g":1,"p":1},{"i":3071,"t":"如何引导孩子制作惯例表？","l":"TF2-2","c":"金凤","g":0,"p":1},{"i":2895,"t":"正面管教工具","l":"TF2-4","c":"李欢","g":1,"p":1},{"i":2701,"t":"在尊重自己和孩子的同时建立良好的沟通模式找到最有效的解决问题","l":"TF1-2","c":"饶晶晶","g":1,"p":1},{"i":2700,"t":"在拆书帮人人都是参与者，大家都在一个平等和谐的环境中成长","l":"TF1-1","c":"饶晶晶","g":1,"p":1},{"i":2679,"t":"如何利用“共情”技巧引导孩子？","l":"TF1-2","c":"金凤","g":1,"p":1},{"i":2075,"t":"共同解决问题的7个步骤","l":"TF1-2","c":"饶晶晶","g":1,"p":1},{"i":2074,"t":"提前说","l":"TF1-1","c":"饶晶晶","g":1,"p":1}],"ms":[{"id":8669,"topic":"带孩子做一次选择轮","learn_goal":"运用选择轮，减少与孩子之间的僵持和冲突，让亲子关系更融洽。","remark":"","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"陈丽青","city":"长沙"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;【自我介绍+主题介绍】\r\n大家好，我是陈丽青，接下来我用三个标签介绍一下自己：\r\n第一个标签：我是一位两个孩子的妈妈\r\n第二个标签：我是归农社交电商新手玩家\r\n第三个标签：我是一位终生学习践行者\r\n学习目标: 今天我们的学习目标，就是通过20分钟的学习让大家掌握一个叫选择轮的工具。当孩子倔脾气来了不合作，运用“选择轮”来减少僵持和冲突，将会让亲子关系更融洽。\u003c/p>\u003cp>\u003cstrong>【FAB】2分钟\u003c/strong>\u003c/p>\u003cp>在开始之前我想简单介绍下《行之有效的正面管教工具》这本书\u003c/p>\u003cp>F：甄颖，美国认证“正面管教讲师”，\u003cstrong>简尼尔森\u003c/strong>亲导中国讲师，深圳汇智有方-正面管教团队 特级讲师，国内点击量（3700万）最高育儿博客“混血小美”博主。\u003c/p>\u003cp>A：你可能看了很多的育儿书，看的时候感觉很厉害，但是回到现实生活中还是素手无策，《行之有效的正面管教工具》这本书就避免了这种情况。因为它针对具体问题会直接给你一个工具和行动指南，让你看完拿起来就能用。\u003c/p>\u003cp>B：孩子不好好睡觉怎么办？孩子调皮捣蛋怎么办？亲子教育的种种问题你都可以直接从《行之有效的正面管教工具》这本书里找到对策，和孩子达成共识，让你成为从容不迫，不急不吼的亲子达人。\u003c/p>\u003cp>大家是不是很期待？\u003c/p>\u003cp>现在，请大家用两分钟时间阅读发给你们的原文拆页，读完请给我一个眼神示意。\u003c/p>","ratings_count":1,"texts":[{"id":12356,"quote":"\u003cp>\u003cstrong>【R】2分钟\u003c/strong>\u003c/p>\u003cp>运用“选择轮”作为正面管教的主要工具\u003c/p>\u003cp>选择轮是在遇到不可调和的问题时，提供几个其他选择，这些选择是孩子和家长共同提出的。选择轮能将不可调和的问题转化成孩子自己能够解决的问题。\u003c/p>\u003cp>\u003cstrong>◆关键态度\u003c/strong>\u003c/p>\u003cp>给予孩子有限的权力:关注解决方法，而不是过分追究原因或责任。\u003c/p>\u003cp>◆技巧\u003c/p>\u003cp>选项是家长和孩子都能接受;\u003c/p>\u003cp>鼓励孩子或和孩子起“头脑风暴”;\u003c/p>\u003cp>最后加一句“你来决定”。\u003c/p>\u003cp>\u003cstrong>◆制作过程\u003c/strong>\u003c/p>\u003cp>1.和孩子坐下来，启发提问孩子:“当问题出现时，例如不愿意按时起床、不想停止看电视 写作业等，你觉得自己可以有哪些解决办法?”\u003c/p>\u003cp>2.用“头脑风暴”的方式提出各种解决方法，然后引导孩子选择可行的解决方法，把孩子的答案写下来\u003c/p>\u003cp>3.用硬纸做一个圆盘，按孩子的答案分成等份\u003c/p>\u003cp>4.请孩子将刚才纸上的答案写或画在圆盘等份上\u003c/p>\u003cp>5.请孩子将“选择轮”挂在他觉得方便的地方\u003c/p>\u003cp>6.整个过程孩子参与越多越好，让孩子做主\u003c/p>\u003cp>7.除了“轮子&quot;，“选择轮”还可以有其他的形式，如选择卡片。\u003c/p>","explains":"\u003cp>\u003cstrong>【I】2-3分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>WHY\u003c/strong>\u003cstrong>：\u003c/strong>作为父母，看到孩子不合作，或者要求他做什么不配合的时候，通常第一反应就是批评、要求孩子按大人的方式来：“先卷起袖子再洗手呀！怎么这都不会？”\u003c/p>\u003cp>但是这样的方式没有用。当你强制孩子去做一件事，只会激发他的逆反心理，跟家长对着干；或者让他讨厌和逃避这件事，再也没有兴趣把它做好。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>WHAT\u003c/strong>\u003cstrong>：\u003c/strong>选择轮是一个小工具，类似于大转盘抽奖。在遇到不可调和的问题时，由家长和孩子共同提出几个其他选择，从而将不可调和的问题转化成孩子自己能够解决的问题。\u003c/p>\u003cp>今天我们将一起来学习如何制作和运用选择轮（勺子也能做选择轮）。学完之后，你将了解到如何通过选择轮让孩子自己找方法，甚至解决一些让家长头疼的坏习惯。\u003c/p>\u003cp>\u003cstrong>举个例子：\u003c/strong>我儿子牛牛，每次幼儿园一放学回家就看电视。\u003c/p>\u003cp>我生气地说：“牛牛，你这样会近视眼的！你为什么不能看看绘本、玩一下玩具呢？每次到商店都喊买玩具，白买了！”可是牛牛依然沉浸在电视里，不给他看就哭。更别说看绘本了。\u003c/p>\u003cp>\u003cstrong>其实根据拆页里的建议，这个时候用选择轮也许会有不一样的结果。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步，头脑风暴。\u003c/strong>\u003c/p>\u003cp>比方牛牛沉迷电视，我抽个时间找他共同想出多个除电视之外的活动，讲故事，捉迷藏等等，并且写下来。“牛牛，如果一直看电视眼睛会受不了，会变成瞎子的！我们来想一想，除了看电视，你还可以玩别的吗？”接着，和牛牛一起在白纸上，把可以玩的项目全部画下来，包括讲故事、捉迷藏、玩积木、看绘本、玩气球……\u003c/p>\u003cp>\u003cstrong>第二步，共同制作。\u003c/strong>\u003c/p>\u003cp>和牛牛一起制作，把选项写在选择轮上。因为这会牛牛非常兴奋，而且愿意使用选择轮来做选择。\u003c/p>\u003cp>\u003cstrong>第三步，共同体验。\u003c/strong>\u003c/p>\u003cp>让牛牛亲自转动选择轮，对他的行动要多多鼓励。 “牛牛，你太棒了，想到了这么多可以玩的项目！下一次觉得无聊的时候，我们就转动选择轮，转到哪儿就玩哪一个，可以吗？”\u003c/p>\u003cp>\u003cstrong>相信儿子一定会乐此不疲，再也不会沉迷电视了！\u003c/strong>\u003c/p>\u003cp>\u003cstrong>PS\u003c/strong>\u003cstrong>：展示选择轮、勺子做大转盘，现场演示。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>HOW\u003c/strong>\u003cstrong>：\u003c/strong>刚才的案例中简单提到了选择轮的做法。实际上它可以分为三步：\u003c/p>\u003cp>第一步，头脑风暴。比方说孩子沉迷电视，家长可以引导孩子共同想出多个除电视之外的活动，讲故事，捉迷藏等等，并且写下来。\u003c/p>\u003cp>第二步，共同制作。和孩子一起制作，把选项写在选择轮上。\u003c/p>\u003cp>第三步，体验鼓励。让孩子亲自转动选择轮，对孩子的行动要多多鼓励。\u003c/p>\u003cp>\u003cstrong>WHERE\u003c/strong>\u003cstrong>：\u003c/strong>选择轮，是一种化解亲子沟通问题、启发孩子思考解决方案的一种方法。需要注意的是，一定要先把双方情绪平静下来，才有心情来探讨制作选择轮。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>其次，不仅是孩子，其实和男朋友、老公之间也可以用选择轮：“老公，每天晚上你在玩游戏之前可以帮我分担一部分家务吗？我知道你有选择困难症，这样，我们来做一个转盘！”\u003c/p>\u003cp>最后，选择轮是调味品，不是主食，不适合天天用、所有场合都用，付出耐心培养孩子的好习惯才是根本。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】 显像提问 激活经验 2分钟\u003c/strong>\u003c/p>\u003cp>OK ，接下来进入A1环节，需要大家激活过往经验，并做讨论和分享。请大家分为2人一组，用1分钟来讨论我们A1环节的问题。稍后我请一位伙伴来分享。\u003c/p>\u003cp>\u003cstrong>提问：回忆一下，最近一个月内，\u003c/strong>\u003c/p>\u003cp>你家孩子是否有跟你对着干？比方说，带孩子出去玩，他偏要买玩具、买零食，怎么劝都不听，把你气个半死？又比方说，反复提醒孩子抓紧时间写作业、少看电视，孩子却当成耳边风，最后不得不骂他一顿，闹得鸡飞狗跳？\u003c/p>\u003cp>没有孩子的伙伴们，可以想下是否有类似的情况，当你想要老公、男朋友分担家务的时候，他却在沙发葛优躺玩游戏？有时候会因为对方不做家务而吵架、闹得不愉快？有请xx来分享一下！\u003c/p>\u003cp>分享者（军哥）\u003c/p>\u003cp>小孩4岁，男孩，很少能够自主玩，如果有自己陪着玩还好，没有就只能电视才能让其安静一会，大多数情况是，自己也不知道可以陪孩子玩什么项目，所以经常被孩子缠着；爸爸，陪我玩一会，不一会就开始没耐心，弄的自己和孩子都不愉快。\u003c/p>\u003cp>\u003cstrong>【A1+】反思加工，讨论分享7-9分钟\u003c/strong>\u003c/p>\u003cp>假如回到当时的问题场景，你能否运用选择轮的方法，和对方共同找到解决方案？你准备什么时间和对方沟通？你的选择轮会做成什么样？请在拆页反面画出你的选择轮~稍后我来请一位伙伴做分享！\u003c/p>\u003cp>另外再重述下制作选择轮的三步骤：第一步，头脑风暴。第二步，共同制作。第三步，体验鼓励。\u003c/p>\u003cp>OK，请xx来分享你的选择轮！\u003c/p>\u003cp>分享者（尹丹）\u003c/p>\u003cp>孩子6岁，自己平时工作忙，孩子由爷爷奶奶带，暑假期间在家基本是早上起来到晚饭时间都在看电视，没啥活动项目。通过今天选择轮的学习，这位分享者想回去，在孩子心情比较好的时候，约上爷爷奶奶一起开个家庭小会议，讨论出孩子的活动项目选择轮并制作出来，在以后觉得无聊没事干的时候可以拿出来让孩子选择活动项目。由于选择必须要孩子共同参与，所以现场没法深入，分享者get到几个注意点：\u003c/p>\u003cp>第一：必须在孩子心情好的时候\u003c/p>\u003cp>第二：选择的项目必须是孩子自己喜欢干的，作为父母不能给孩子下套，让孩子感觉就是不让他看电视，否则孩子也不配合。\u003c/p>\u003cp>第三：针对选择轮项目的数量和质量，分享者也有想到。项目不宜过多，同事也许可以针对看电视一个项目设置不用时间长度的选择轮。\u003c/p>\u003cp>非常感谢这位分享者的积极参与和分享，给我很大齐启发。\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>好的！今天我们学习了一种亲子之间化解问题、共同寻找解决方案的方法，叫选择轮。其实，批评和说教很多时候会起反作用；反过来，没有人会讨厌选择轮这样轻松的小游戏。我的分享结束了，请大家多多指教！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1566314317000,"updated_at":1566314347000,"ria":true},{"id":3832,"topic":" 如何鼓励孩子，让他成为一个自信的人？","learn_goal":"学会5种鼓励的技巧，帮助孩子成为自信的人","remark":"这本书用工具式编排和案例式分享大幅降低家长接受正面管教的门槛；\r\n最接地气：本书精选的12个正面管教工具，是三年里正面管教讲师和妈妈评价“受益最多、效果最显著的”；\r\n真实有效：本书所有案例全部由中国新知家庭提供，均是发生在家庭里的真实管教故事；\r\n点评诚恳有力：身为前欧洲媒体记者、拥有跨国婚姻的甄颖，具有国际化视野，她的点评简洁有力，直指人心。\r\n当面对孩子的挑战你手足无措时，一起来学拆解这本书！","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"王文婷","city":"西安"},"club":{"name":"西安古城分舵","city":"西安"},"prologue":"我的名字叫王文婷。是这家亲子绘本馆的创始人之一。曾经做过酒店HR。我的三个标签：1.一个2岁小鲜肉的妈妈。2.用生命在讲故事的故事姐姐。3.拆书帮打怪萌新（萌萌哒新人），希望以后我的这个标签会变成：一级拆书家，二级拆书家，三级拆书家。二、拆书帮介绍：\r\n“拆书”1.是一种学习方法论。 2.适用于以提升能力、解决问题为目标的成人学习。 3.强调以学习者为中心而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。 4.分为个人学习的拆书法和组织学习的拆书法：个人学习的应用是便签法，让人读一本书就能达到参加同主题培训的的效果；组织学习的应用是现场拆书法，一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。 5.拆书形式为RIA：R为阅读原文片段；I为自己的理解；A有三种形式，A1为关联以往经验，指向过去；A2为规划今后具体的应用，指向未来；A3为现场演练，在拆书家引导下现场学习并且练习。 \r\n “拆书帮”是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵（也叫拆书俱乐部）。拆书帮分舵是公益性青年自组织，其使命是帮助更多学习爱好者成长为拆书家。","ratings_count":0,"texts":[{"id":6763,"quote":null,"explains":"\u003cp>赞美孩子，家长总是用自己的期望去衡量孩子的行为，这样容易让孩子觉得做什么都是为了别人做，是为了达到别人的期望。这会使孩子对“自我价值”的深刻认识和创造出现偏差。其实赞美也是正向积极的，就像糖果，偶尔使用没关系，大部分人都喜欢吃糖果，但太多会上瘾。赞美长期使用会让孩子过于在意外界的评价。\u003c/p>\u003cp>鼓励孩子的话，事件的主角是孩子，而不是家长。关注点在孩子做了哪些努力，取得了哪些进步。出发点在孩子自己，这样更容易激发孩子的内动力，自己去达成想要做的事。鼓励可以帮助孩子建立正确的自我认知和信任。\u003c/p>\u003cp>鼓励技巧：1、尽量不给孩子贴标签，不拿孩子跟别人比较（无论怎样我都爱你）2、客观鼓描述孩子值得鼓励的行为和结果（妈妈看到你收拾了书桌，你把钢笔、铅笔都进行分类，放在不同的盒子里，书桌很整洁）3、关注并说出孩子的感觉，而不是大人的感觉（你一定很为自己骄傲）”4、指出孩子的小进步（孩子考了不及格，妈妈说：妈妈看了你这次考试卷，有一道题你上次做错但这次你做对了，有进步噢）5也可以客观表述孩子值得赞赏的行为之后总结一两个标签词（你把钢笔、铅笔都进行分类，放在不同的盒子里，这就叫有条理）\u003c/p>","interaction":"\u003cp>\u003cstrong>A1：\u003c/strong>\u003cstrong>在一次正面管教拆书课上，老师问我们当你的孩子做了一件你认为还不错的事的时候你是怎么表扬他的？当时我的分享是：有一天下午，我的孩子seven摆弄起了他的尿不湿，他把尿不湿一包一包排成一列并且告诉我：“妈妈，你看，小火车。”当时我挺惊喜的，觉得孩子真是太有创意了，随口就说：“哇，seven你好棒啊，你咋这么厉害呢？”然而说完就完了。我这也算及时回应了。但是听完那次拆书，让我了解到仅仅赞美对孩子的未来并没有太多好处，同时也学到了鼓励的技巧。前两天seven又玩了一次尿不湿摆小火车，我微微一笑说：“妈妈看到你把尿不湿摆的很整齐，摆成了一列，你说这是小火车，很有创意哦。我看到你这次摆的小火车还专门摆了火车头，比上次摆的没有火车头的小火车更像火车噢！你要坐哪节车厢？”当我说完seven高兴的挑了一节车厢坐了上去，并且还邀请了我。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>A2\u003c/strong>：\u003cstrong>1、为期一周，每天观察孩子，在发现孩子有值得鼓励的地方，利用鼓励的技巧进行鼓励，并且记录，贴在冰箱上。每天记录至少五条。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2、为其一周，每天观察老公，当他做了一件我认为还不错的事情的时候，及时描述出来并表达我的感谢，每天至少一次。\u003c/strong>\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1507965852000,"updated_at":1507965852000},{"id":3580,"topic":" 当身边的人出现负面情绪时，如何利用“共情”和他们建立连接？","learn_goal":"学会与身边人建立共情，理解他们的负面情绪","remark":"这本书用工具式编排和案例式分享大幅降低家长接受正面管教的门槛；\r\n最接地气：本书精选的12个正面管教工具，是三年里正面管教讲师和妈妈评价“受益最多、效果最显著的”；\r\n真实有效：本书所有案例全部由中国新知家庭提供，均是发生在家庭里的真实管教故事；","level":"TF1-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"王文婷","city":"西安"},"club":{"name":"西安古城分舵","city":"西安"},"prologue":"大家好！我的名字叫王文婷。上周升级打怪时过了1-1，但是1-2失败了！不过失败算什么？我玩剧本推理的时候没有一次成功的，然而我确把剧本推理变成了自己的爱好！那么1-2的小怪兽我又来了，不管你爱不爱我，反正我是爱上你了。爱你就要拿下你！ 我要拆的这本书叫做《行之有效的正面管教工具》，作者甄颖，美国认证“正面管教讲师”，是正面管教创始人简尼尔森亲导的中国讲师。本书收录了12个深受中国家长欢迎的代表性正面管教工具，让你轻松入正面管教的大门。","ratings_count":0,"texts":[{"id":6474,"quote":"\u003cp>\u003cstrong>如何使用“共情”达到情感连接？\u003c/strong>\u003c/p>\u003cp>◆含义\u003c/p>\u003cp>“共情”是心理学术语，又叫同感、同理心。\u003c/p>\u003cp>共情的过程是：一、辨认孩子的感觉，包括正面感觉和负面感觉；二、准确地用语言表达出来。\u003c/p>\u003cp>◆关键态度\u003c/p>\u003cp>接纳并认可孩子的负面情绪，教会孩子感觉没有错，但行为不可以。\u003c/p>\u003cp>◆技巧\u003c/p>\u003cp>找到孩子负面情绪的开始点；\u003c/p>\u003cp>识别孩子负面行为后面的情绪并表达；\u003c/p>\u003cp>找到孩子有这样负面情绪的道理或事实原因；\u003c/p>\u003cp>猜或说出孩子的愿望的。\u003c/p>","explains":"\u003cp>在孩子有负面情绪时，说教惩罚会使孩子更受伤害，但力图立刻修复或解救孩子，这种不想让孩子失望的做法同样是对孩子的不尊重，它剥夺了孩子培养“抗挫折力”的机会；\u003c/p>\u003cp>在你的亲人和朋友生气、烦躁、伤心时，只是聆听怕显得不够关心，说的太多又怕说不到对方心坎里。\u003c/p>\u003cp>那么该如何做好第一步呢？\u003c/p>\u003cp>\u003cstrong>这时首先要做的是通过\u003c/strong>\u003cstrong>认可和\u003c/strong>\u003cstrong>接纳\u003c/strong>\u003cstrong>他们\u003c/strong>\u003cstrong>的情绪跟\u003c/strong>\u003cstrong>他们\u003c/strong>\u003cstrong>建立联结，也就是我们经常说的“共情”(同理心）。\u003c/strong>\u003c/p>\u003cp>可以按照以下几个步骤进行：\u003c/p>\u003cp>1. \u003cstrong>识别\u003c/strong>\u003cstrong>他们\u003c/strong>\u003cstrong>负面情绪\u003c/strong>\u003cstrong>是什么\u003c/strong>\u003cstrong>并且说出来\u003c/strong>：伤心、难过、生气等\u003c/p>\u003cp>2. \u003cstrong>找到产生负面情绪原因并且说出来\u003c/strong>：摔倒了、失败了、恋人劈腿了等\u003c/p>\u003cp>3. \u003cstrong>分析\u003c/strong>\u003cstrong>并且说出来\u003c/strong>\u003cstrong>他们\u003c/strong>\u003cstrong>当下的愿望\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;\u003cstrong>当你做完这三步，认可并接纳他们情绪的时候，他们的情绪已经得到了初步的稳定，心情也会变得稍微好一些。接下来你们的沟通会变得更容易一些。\u003c/strong>\u003c/p>\u003cp>举一个我的\u003cstrong>例子\u003c/strong>吧：\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;很久很久以前，我老公和我散步，聊起了他上班时的一些不愉快。同事勾心斗角、领导抠门事儿多。当时听完我就火冒三丈，我立即气急败坏的骂了他同事和诅咒了他领导。回头看见我老公，只见他不停的摇头显得更加烦躁。他本想和我道道苦水，也就罢了。不料我把他工作中的问题无限放大和加重了。这并不是他想要的。后来看完了这本书，学会了共情。遇到了老公同样的吐槽，我换了做法：听完你刚才说，我能感觉到你现在挺郁闷的，你的那个同事确实是一个心胸狭窄之人，总是见不得别人比她好，所以总是给你穿小鞋。你是不是特别不想和她一个部门啊？我老公连连点头。然后他自己想通了说：确实不想和她一起共事了。算了吧，出来工作，怎么可能事事顺心，尽量和这种小人保持距离吧。\u003c/p>","interaction":"\u003cp>A1激活经验\u003c/p>\u003cp>接下来请各位小伙伴想一个你在生活中经历过\u003cstrong>失败共情的案例\u003c/strong>，在小组内分享，时间是5分钟。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;请哪位小伙伴愿意代表大家分享一下自己关于共情失败的案例。\u003c/p>\u003cp>诗悦：有一次我妈妈和我抱怨说我爸爸非要拉她早起去超市买优惠特价菜，我妈想多睡一会。她向我抱怨，巴拉巴拉说了很多。我没有很在意就跟她说：哎呀你就跟他说不想去不就行了。然后就没有再去安抚她。现在觉得这样做挺不对的。\u003c/p>\u003cp> &nbsp; &nbsp;A2催化应用\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;大家已经学习到了共情，那么请各位伙伴在便签纸上写下\u003cstrong>应用“共情”的规划\u003c/strong>。要包含具体做法，有明确时限和可衡量或可观测的预期结果。时间1分钟。\u003c/p>\u003cp>诗悦:下周末回家看父母，当妈妈向我再次抱怨爸爸时，我就用今天学到的共情技巧安慰妈妈：1我明白你现在的感受，你很郁闷是吗？2是因为爸爸做了什么什么事3其实你特别想要如何如何，对吗？\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1504448640000,"updated_at":1504943585000,"ria":true},{"id":3533,"topic":"鼓励和赞美","learn_goal":"学会运用鼓励技巧帮助孩子性格及能力发展","remark":"赞美像糖果，可以偶尔使用，但是太多，可能令孩子容易上瘾，容易趋向取悦他人，对“自我价值”的深刻认识和创造不健康。而鼓励，则帮助孩子对自己性格的长处和能力得到发展，培养自信，而不是他信。","level":"TF2-3","duration":30,"status":0,"type":0,"chaishujia":{"username":"金凤","city":"东莞"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是拆书家黄金凤，当孩子做得好时，我们习惯性的赞美是;你真棒，但长此以往，孩子听了太多诸如此类空泛的赞美，并不确定自己哪里做得好哪里要改进，而且会依赖别人的评价，容易他信而不是自信，那么相对于赞美而言，鼓励关键是什么，有什么技巧，实践中要注意什么，接下来会在我们拆书过程中作分享，在拆书前先分成两个组，左边一组右边一组。","ratings_count":0,"texts":[{"id":6416,"quote":"\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>F:\u003c/strong>我们今天分享的书名为《行之有效的正面管教工具》，作者甄颖，“正面管教”40年前源于美国，以奥地利心理学家的“个体心理学”理论为基础，由简尼尔森和琳洛特等教育专家完善，是一个专注相互沟通的，体验式的家长教育体系。本书讲述的主要就是如何运用正面管教方法使孩子获得这种能力。\u003c/p>\u003cp>\u003cstrong>A:\u003c/strong>本书具体有以下四大优势：\u003cbr> 1、工具式编排和案例式分享大幅降低家长接受正面管教的门槛；\u003cbr> 2、12个正面管教工具好评如潮非常接地气，；\u003cbr> 3、管教故事真实有效；\u003cbr> 4、国际化视野角度点评诚恳有力，直指人心。\u003cbr> \u003cstrong>B:\u003c/strong>面对日常教育类书籍阅读中，学术类的和带案例讲解类的书，哪类你会更感兴趣？国外的案例和实践过的中国老百姓案例，哪个对你更有借鉴意义？大部分人都会选择后者，而本书恰好戳中这些痛点，满足我们家长的喜好，正面管教工具一目了然，家长们不但从书中学到易学实用的方法和工具，还可从真实的具有言传身教效果的实际案例中模仿演练，解决孩子睡觉吃饭拖拉，不听指令、轻易放弃等日常问题，帮助家长找到引导孩子自信，自律，拥有强大内心力量的成长途径。\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>请大家在跟随我完成本次RIA现场学习后，\u003cstrong>学会运用鼓励技巧帮助孩子性格及能力发展\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>R原文片段：\u003c/strong>\u003c/strong>《行之有效的正面管教工具》第208页\u003c/p>\u003cp>鼓励VS赞美，赞美像糖果，可以偶尔使用，但是太多，可能令孩子容易上瘾，容易趋向取悦他人，对“自我价值”的深刻认识和创造不健康。而鼓励，则帮助孩子对自己性格的长处和能力得到发展，培养自信，而不是他信。\u003c/p>\u003cp>关键态度：事件的“主角”是孩子不是家长。\u003c/p>\u003cp>技巧：尽量不给孩子贴标签，不拿孩子跟别人比较；对孩子的行为结果“照镜子”，客观描述孩子值得鼓励的行为和结果；关注并说出孩子的感受，而不是大人的感受；指出孩子的小进步（即使再糟糕的情况，也有值得称赞的地方）；也可以在客观描述孩子值得赞赏的行为后，总结为一两个“标签”词。\u003c/p>","explains":"\u003cp>\u003cstrong>【亲身案例】\u003c/strong>为了鼓励孩子睡前刷牙的习惯，当孩子自己刷牙时候对孩子说的最多的一句话就是孩子你真棒。这一招一开始对孩子来说非常受用，我一说你真棒，你刷得真好，孩子就会拿着牙刷自己开始刷起来，但是说得多了，孩子好像也没有一开始的时候表现积极，把牙刷给孩子时，有时会提出“妈妈你帮我刷嘛”这种请求，甚至有时会说累了我不刷然后躺在床上，怎么哄都不愿意刷，可见，这种泛泛的“你真棒”外在赞美方式未能真正持久驱动孩子的内在动力。\u003c/p>\u003cp>\u003cstrong>【原文拆解】\u003c/strong>原文提到，鼓励重点在于“励”赞美重点在于“美”，前者强调让事件的主角孩子主动积极做出改善的行为，调动孩子自己的内在驱动力，而后者极容易造成过度赞美，导致孩子变成“讨好者”，总是想获得他人的认可，调动的是孩子的外在驱动力，一旦外在驱动力没有了，孩子就没有动力了。我们的主要目的是让孩子自信自立，所以，面对孩子不良行为，要善于运用启发式语言引导孩子自我发现、自我改进、自我提高。对于孩子不会做的事情，要花一些时间通过训练让孩子学会。\u003c/p>\u003cp>\u003cstrong>【细化原文技巧】\u003c/strong>为了帮助孩子性格和能力获得更客观更持续的发展，我们可以这么尝试运用原文提到的关键技巧去鼓励：\u003c/p>\u003cp>\u003cstrong>1、 照镜：\u003c/strong>\u003c/p>\u003cp>a、做孩子的镜子，即客观描述孩子值得鼓励的行为和结果，对其行为或结果照镜子，描述你所看到的，你感受到的；例如说：孩子今天你主动去拿牙刷来刷牙，还创造左右刷牙方式…… \u003c/p>\u003cp>b、引导孩子自己照镜子，即引导孩子关注自己好的地方，引导孩子学会自己对自己作评价、例如说：刚刚是不是这样子上下刷？你看一下镜子，上下的门牙都刷得非常干净呢……\u003c/p>\u003cp>c、告诉孩子犯错误也是学习的好时机。例如说：刚刚我们虽然用这根粗的绳子没法穿过这个珠子，但是我们也相当于发现了，这么粗的绳子是无法穿过的，那我们要不要尝试下用细一点的绳子呢……\u003c/p>\u003cp>\u003cstrong>2、 共情：\u003c/strong>\u003c/p>\u003cp>a、共情以孩子为出发点，关注并说出孩子的感受，是孩子的感受而不是大人的感受，这里重点是观察孩子行为帮助他说出来，让他看到；例如说：妈妈知道到你很想再听妈妈讲多一个故事……\u003c/p>\u003cp>b、共情需准确及时，当孩子发生情绪改变时候，当孩子出现不当趋势时，需尽早共情，并用准确词语表述，让孩子相信你是跟他站在一起的，例如说：妈妈小的时候也是不怎么喜欢刷牙……\u003c/p>\u003cp>c、共情可尝试拥抱等方式，大一些的孩子可采用摸摸头拍拍肩等肢体语言，或者纸条信息传递等，这种方式我经常使用，作为爱的语言表达方式，孩子现在看到我难过的时候也会抱抱我说没事的……\u003c/p>\u003cp>\u003cstrong>3、 指向：\u003c/strong>\u003c/p>\u003cp>a、指向是正向的，即指出孩子的小进步引导新的动作或行为，即使孩子有做得不当的行为，也是可以通过指向式鼓励来解决的，每当我对着2岁多的儿子说：“你刚刚帮妈妈叠衣服，真是妈妈的好帮手”时，我们家孩子就非常得意，还屁颠屁颠叠把衣服抱到柜子里面。\u003c/p>\u003cp>b、指向旨在激发内在驱动力，指向时候注意引导孩子学会自力更生，觉得自己有价值，无需他人的评价认可 ，例如说：我知道你有很多新的主意及办法，你觉得遇到这个问题还有什么办法呢？\u003c/p>\u003cp>c、指向过程中可用启发式的语言帮助孩子改进，用充满乐趣的游戏方式来进行训练，或者用惯例表让孩子学会正确指向行为练习。例如：我们来玩一个保护米饭的游戏吧，如果谁吃饭的时候把米饭一颗不剩地从碗里送到嘴里，谁将获得一个故事卡，好吗？\u003c/p>\u003cp>\u003cstrong>4、 标签：\u003c/strong>\u003c/p>\u003cp>a、给行为填标签，仪式化，即将值得赞赏的行为，总结为一两个“标签”词并鼓励继续该该习惯或能力。例如说：尽管你现在有点困了，但你今天仍然拿起牙刷刷牙，这叫“坚持”。 \u003c/p>\u003cp>b、不给孩子贴标签，不拿孩子跟别人比较，我们总是看不到孩子身上90%的优点，而只看到了10%的不足，我们家长应尽量避免说： “你真是个顽固的家伙”这类负面负面标签的话。\u003c/p>","interaction":"\u003cp>【A3】促动参与\u003c/p>\u003cp>拆书家提问设计（逐字稿）\u003c/p>\u003cp>【场景】我们刚刚学习了可以鼓励四步法来替代赞美或者指责纠正孩子，现在一起来做一个演练。演练背景是这样子的：孩子从客厅跑到你的房间，手里拿着一张纸，上面是各种彩笔的涂鸦，放在你的面前问你：“画得好看吗？” \u003c/p>\u003cp>现在，两人一组作角色扮演练习，一个人扮演孩子，另一个人扮演家长，请扮演家长的角色运用鼓励四步法来作引导，演练万后再作角色互换。\u003c/p>\u003cp>演练时间3分钟，现在开始，3分钟后，我会选一组来作角色扮演及对话，大家一起观察及听听家长是如何运用鼓励四步法工具，以及孩子是什么反应的。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学员晓勤：扮演女儿，学员佐旭：扮演父亲\u003c/p>\u003cp>女儿：爸爸，爸爸，你看看我画的画。\u003c/p>\u003cp>爸爸：嗯。我看到你画了一大片绿绿的草地、还有蓝天。用色比之前画的丰富多了，画的东西也比之前多了呢。哦，这边还有一栋好漂亮的房子呢。\u003c/p>\u003cp>女儿：爸爸，你觉得这栋房子好看吗？\u003c/p>\u003cp>爸爸：好看啊，这房子还有点眼熟呢。\u003c/p>\u003cp>女儿：爸爸，难道你忘了吗？前不久，你带我和妈妈去过的啊，我们去那里玩啊。\u003c/p>\u003cp>爸爸：哦，原来，你是画上次我们去旅游，在郊区住的那所房子啊，怪不得我看着这么熟悉呢。\u003c/p>\u003cp>女儿：是的。\u003c/p>\u003cp>爸爸：宝贝，你还有写生的能力，有小画家的潜质哦，真不错。\u003c/p>\u003cp>\u003cstrong>【点评】\u003c/strong>非常感谢两位精彩演绎，刚刚爸爸角色扮演者巧妙地运用了鼓励提到的方法，例如说运用到了照镜的方法，表达我看到的如绿绿地草地、蓝天等；运用了指向的方法例如画得更丰富了、有写生的能力等；运用了标签的方法例如有小画家的潜质等，刚作为孩子的扮演者也表达了她受到了鼓舞，这些方法都驱动了孩子的内在驱动力，促使孩子画得更丰富、更有趣、更多写生，并朝着小画家前进，这些都是鼓励强调的方法及效果。\u003c/p>\u003cp>【小结】通过刚刚拆解及练习，相信大家对鼓励及赞美的区别有一定了解，并通过练习对鼓励四步法照镜、共情、指向、标签加深了印象，希望在接下来与孩子相处中能应用鼓励方法，调动孩子自己的内在驱动力，帮助孩子性格和能力获得更客观更持续的发展。本次分享到此结束，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1504092847000,"updated_at":1504093127000,"ria":true},{"id":3491,"topic":"如何教会孩子将日常的行为习惯制作成惯例表？","learn_goal":"学会引导孩子制作有效的惯例表 ","remark":"关键是找到需要制作惯例表的时间段，通过启发式提问和“头脑风暴”，引导孩子想出时间段内的事情和内容；引导孩子将内容排列出顺序；可以用照片、画画、贴纸等各种方式完成制作；与孩子参与，越多越好。","level":"TF2-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"金凤","city":"东莞"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是拆书家黄金凤，有什么办法可以避免混乱的学习或者生活工作状态，有人脑海中立刻想到了一种办法，就是做计划，这是个好办法，学生上课有课程表，工作时候有工作计划，那么针对幼儿时期孩子是否有一种避免失控局面的方法，有专家提出思考，可以建立一种习惯规律养成表也就是惯例表，那么现在新的问题就来了，惯例表的制作是大人做还是孩子做？怎样的惯例表才是对孩子真正有效的惯例表？在接下来的拆书中会分享如何引导及制作这种帮助孩子自律的惯例表。在拆书前先分成两个组，左边一组右边一组。","ratings_count":0,"texts":[{"id":6368,"quote":"\u003cp>R：《行之有效的正面管教工具》第104页\u003c/p>\u003cp>本章运用惯例表作为正面管教的主要工具。\u003c/p>\u003cp>含义：惯例表，就是把日常应有的行为习惯，通过书写、画画等方式表现出来。它还有不同的名字:日程表，规律表等等。\u003c/p>\u003cp>关键态度：给以孩子掌握自己生活的权力。\u003c/p>\u003cp>技巧：找到需要制作惯例表的时间段；通过启发式提问和“头脑风暴”，引导孩子想出时间段内的事情和内容；可以用照片、画画、贴纸等各种方式完成制作；让孩子参与，越多越好。\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>F:\u003c/strong>我们今天分享的书名为《行之有效的正面管教工具》，作者甄颖，“正面管教”40年前源于美国，以奥地利心理学家的“个体心理学”理论为基础，由简尼尔森和琳洛特等教育专家完善，是一个专注相互沟通的，体验式的家长教育体系。本书讲述的主要就是如何运用正面管教方法使孩子获得这种能力。\u003c/p>\u003cp>\u003cstrong>A:\u003c/strong>本书具体有以下四大优势：\u003cbr> 1、工具式编排和案例式分享大幅降低家长接受正面管教的门槛；\u003cbr> 2、12个正面管教工具好评如潮非常接地气，；\u003cbr> 3、管教故事真实有效；\u003cbr> 4、国际化视野角度点评诚恳有力，直指人心。\u003cbr> \u003cstrong>B:\u003c/strong>面对日常教育类书籍阅读中，学术类的和带案例讲解类的书，哪类你会更感兴趣？国外的案例和实践过的中国老百姓案例，哪个对你更有借鉴意义？大部分人都会选择后者，而本书恰好戳中这些痛点，满足我们家长的喜好，正面管教工具一目了然，家长们不但从书中学到易学实用的方法和工具，还可从真实的具有言传身教效果的实际案例中模仿演练，解决孩子睡觉吃饭拖拉，不听指令、轻易放弃等日常问题，帮助家长找到引导孩子自信，自律，拥有强大内心力量的成长途径。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>请大家在跟随我一起完成本次RIA现场学习后，\u003cstrong>学会引导孩子制作有效的惯例表，\u003c/strong>还孩子自主权。\u003c/p>","explains":"\u003cp>\u003cstrong>【I】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【亲身案例】\u003c/strong>为了培养孩子喜欢运动，音乐，阅读，自律等习惯，我曾经给孩子做过这么一个惯例表：7：30起床后磨耳朵，13：00午休,20：30睡前音乐，20：30上床喝牛奶讲故事,21：00关灯，饭前饭后洗手，睡前刷牙\u003c/p>\u003cp>\u003cstrong>【案例失败结果】\u003c/strong>然而，尽管这个惯例表已经做得非常简单易行，但实际是有些规则并不受孩子待见，例如睡前刷牙，到了规定时间，孩子找各种借口不配合刷牙甚至拒绝刷牙，有时候睡前放音乐孩子说我要听故事，回到家有时候还是会喜欢穿着鞋子直奔游戏区……\u003c/p>\u003cp>\u003cstrong>【原文拆解】\u003c/strong>阅读原文后发现，这个计划是我的计划而不是孩子自己的计划。根据原文片段，属于孩子的惯例表应该让孩子更多地参与制作惯例表的过程，通过启发式提问和“头脑风暴”，引导孩子想出时间段内的事情和内容并作排序，最后用一些有趣的方式可视化。这里强调给予孩子掌握自己生活的权力，帮助他们建立自律的性格。\u003c/p>\u003cp>\u003cstrong>【拆页行动建议】\u003c/strong>接下来我会使用原文提到以下4个方法制作惯例表\u003c/p>\u003cp>1、 \u003cstrong>找到需要制作惯例表的时间段，从“简单惯例”及“已有惯例”入手：\u003c/strong>\u003c/p>\u003cp>孩子一天二十四小时全部都规划得分秒不剩，孩子基本没有自由的空间，也不利于孩子发展，惯例表仅针对“需要的”的时间段作规划，例如起床后睡觉前，上学前放学后等，学习日和休息日，通过引导孩子创建自己的跳一跳就能达成的惯例表，来帮助他学习时间管理和生活安排，会增加惯例表的有效性；从孩子熟悉的“简单惯例”及“已有惯例”开始，孩子容易实施和执行，孩子更有成就感。\u003c/p>\u003cp>2、 \u003cstrong>启发式提问和“头脑风暴”确定要做的事项，不打断不赞美不评价 \u003c/strong>\u003c/p>\u003cp>运用启发式提问一步步引导孩子自己想出每天要做的事情，孩子说，家长记录，为避免唠叨，当孩子忘了可提示：“你的惯例表下一项是什么？与孩子一起“头脑风暴”时候，通过照片图片等给孩子提示联想及思考，在孩子全部说完之前，家长最好不要打断，不赞美不评价，当跟孩子确定他说完了，可以补充：“再加上刷牙怎么样？吃完饭后接下来我们要做什么呢？ ”\u003c/p>\u003cp>3、 \u003cstrong>可以用照片、画画、贴纸等各种方式完成制作，作可视化有趣呈现 \u003c/strong>\u003c/p>\u003cp>例如讲故事等孩子做过的事情或者场景照提前打印出来；一些像自己洗澡、自己收拾东西等未来计划做的事项，提前在百度找出相关彩图并打印出来；一些像洗手，牛奶等比较容易画的事项，可以打印一份留着现场跟孩子现场上色或者一起画出来（根据时间进行调整）做好计划后提示与孩子一起排序，例如：我们一起来将这些有趣的事情排个队如何？ \u003c/p>\u003cp>4、 \u003cstrong>\u003c/strong>\u003cstrong>让孩子更多参与，让“惯例表做主”代替“\u003c/strong>\u003cstrong>唠叨\u003c/strong>\u003cstrong>” \u003c/strong>\u003c/p>\u003cp>从想计划，排序计划，画出场景，粘贴场景，到每个执行环节，都由孩子自主思考、参与、动手制定规律及执行规则。每做一件事情就来到惯例表面前指给孩子看，并鼓励引导他想出下一个行动动作，把培养孩子习惯的工作交给日常惯例表，而不是告诉他该怎么做。为避免唠叨，当孩子忘了可提示：“你的惯例表下一项是什么？”即可，例如：我们回家先要怎么办，手洗完之后我们接下来要干什么事情呢……\u003c/p>\u003cp>\u003cstrong>【预防可能的异议】\u003c/strong>\u003c/p>\u003cp>有人可能会觉得孩子这么小，要求这么多，孩子多累啊，殊不知，每天都发生各种各样的新鲜事，大大小小的事情都会在不断变化中，建立惯例表，一切变成可预知的，遇到问题有明确的指引，孩子反而觉得生活更规律，更有安全感；让孩子早点参与制作他们的惯例表，会让他们更有归属感和成就感；孩子越小越值得尝试，因为提前训练比纠正来得更轻松。\u003c/p>\u003cp>更有一些人疑虑，惯例表心里有数就好，没必要用这么正规的方式呈现吧，就算做出来了，孩子不执行那岂不是白费劲啦？惯例表可视化会让孩子更容易理解及执行，从而让孩子更有成就感；过了新鲜期，孩子不执行惯例表也没有关系，惯例表执行过程也是螺旋式上升过程，只要不断尝试不断调整不断坚持前进，激发孩子内心的强大驱动力，孩子会比大人更加自律。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2】催化应用（分步骤化1）\u003c/strong>\u003c/p>\u003cp>【拆书家提问设计（逐字稿）】请想象一下，在未来的一周，你可能会遇到以下哪种让你感觉焦虑的情景？孩子晚上不想睡觉、早上不想起床，想一直听很多很多的故事，想吃某样食物但不想洗手，进门不换拖鞋直奔游戏区……请一两位伙伴跟我们分享下。\u003c/p>\u003cp>【学习者案例记录】学员楚瑜案例：\u003c/p>\u003cp>我家女儿睡前非常喜欢听妈妈讲故事，未来一周，暑假马上结束、要回归学校生活，我们可能会遇到的情景是：睡前故事时，讲完一个故事之后、女儿还会继续要求再讲一个、再讲一个。这时，我想到如果第二天早上女儿要上学、需要早起，就会很焦躁。\u003c/p>\u003cp>非常感谢楚瑜的分享。\u003c/p>\u003cp>【A2】催化应用（分步骤化2）\u003c/p>\u003cp>【拆书家提问设计（逐字稿）】请大家想一下，针对刚刚想到的未来可能发生的情境，你将如何应用今天拆页中学到的找时段、启发提问头脑风暴、有趣呈现、激励参与四个方法，制作有效的惯例表？请简要写在便签上，一会请一两位伙伴分享一下。\u003c/p>\u003cp>【学习者案例记录】学员楚瑜案例：\u003c/p>\u003cp>第一步：与孩子正式沟通，定下睡觉时间。\u003c/p>\u003cp>第二步：跟孩子谈谈，为了保证准时睡觉，如何做？\u003c/p>\u003cp>第三步：把我们刚刚讨论的如何做，用文字+图片记录下来。\u003c/p>\u003cp>第四步：每天重复运用、适时调整。\u003c/p>\u003cp>\u003cstrong>【小结】\u003c/strong>感谢晓瑜分享\u003cstrong>，\u003c/strong>相信大家通过刚刚的分享及练习学会怎么应用找时段、启发式提问和头脑风暴、有趣呈现等技巧，引导及与孩子一同制作属于孩子自己的惯例表，与其花更多时间去纠正未经训练的行为，不如我们花时间提前制定惯例表训练正确的行为，让孩子更有安全感，让孩子更有自律。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1503568879000,"updated_at":1503569498000,"ria":true},{"id":3241,"topic":"用拥抱来解决各项冲突","learn_goal":"拥抱工具","remark":"正面管教体系是近40年前源于美国，以奥地利心理学家阿德勒和德雷克斯的“个体心理学”理论为基础，由简.尼尔森和琳》洛特等教育专家完善，是一个专注相互沟通的，体验式的家长教育体系。我们可以通过正面管教的工具学到易学实用的方法，来解决孩子睡觉，做事拖拉，不听指令，轻易放弃等日常问题，同时还能帮助家长找到引导孩子自信、自律，拥有强大内心力量的成长途径。本书按照家长学习偏好，以12个深受中国家长欢迎的代表性工具入手，用家长真实安全来介绍正面管教的方法和理念。\r\n","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"素颜","city":"沈阳"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是今天带大家拆书的拆书家。我叫王蕾，简单介绍一下自己\r\n1、我是金牛座的，性格特点完全符合金牛座的特点。从兴趣爱好来看呢，我属于那种爱好广泛但都不太精通的人，但是比较喜欢读书，这也是我参加拆书帮的一个原因。在最开始的30个便笺拆书训练的过程中，感觉非常好的，拆得也非常的HIGH， 所以一直想把拆书这件事儿进行下去，希望在以后的拆书过程中能够与大家更多地进行交流。\r\n今天，我们要共同拆解的书籍是：《行之有效的正面管理工具》，这本书是基于《正面管教》这本书总结出来的适合中国家庭的12个正面管教工具，书的特点是操作方法和案例相结合，具有清晰的操作步骤以及在实际案例中的运用效果，非常容易理解。从而大幅度降低家长接受正面管教的门槛。那么什么是正面管教呢？它是一种即不用严厉也不用娇纵的方法，以相互尊重与合作为基础，通过以此为基石，在孩子自我控制的基础上，培养孩子的各项生活能力。下面我们就开始今天的片段阅读","ratings_count":0,"texts":[{"id":6074,"quote":null,"explains":"\u003cp>1、今天我们的片段其实很简单，就是学会拥抱。什么时候拥抱呢？当孩子闹情绪的时候要抱。使用的时候注意事项是：一先要抱然后再和孩子讨论闹情绪的因果；二是要及时抱，当孩子有情绪的那一个时间段就要通过拥抱来安抚。三是抱的时候一定要特别有爱特别温暖地抱抱。实施难点在于，孩子不想抱，这时候或是让孩子抱你，或是给孩子两分钟时候准备，再抱。这个工具是用来安抚和控制孩子负面情绪的良方，通过先抱和孩子产生情感上、身体上的联接后，再讲说教渗透进去，孩子能够更容易接受和理解。\u003c/p>\u003cp>2、举个例子：我家孩子小的时候，我经常陪他玩搭积木的游戏，可是每每搭积木的时候，我都奇困无比，总是昏昏欲睡，每次我睡着后被小孩子闹醒，我都要费尽口舌来安抚这小子，他还一定高兴。当我接触正面管教以后，每次我不小心睡着的时候，被小家伙弄醒以后，我都是抱着他胖胖的小身子，抚摸他的后背，然后说：哎呀，宝贝儿，对不起，我实在太困了，一不小心就睡着了，真是对不起，你肯定觉得我特别敷衍你，特别不重视你，我能感觉到你很生气。你看有什么法子能让我不睡觉啊？一般这时候，他都会转着小眼睛想主意，不是搞成比赛式的，就是通过出难题的方式来惩罚我，当我不过关的时候，或是输给他的时候，他还挺开心的，会把刚才的不愉快忘记。后来，慢慢就变成了，他自己玩，我躺着睡，他搭好了叫醒我，然后给我演示和讲解，他开始慢慢接受我很困的事实了，也能体谅我工作很累的状态。\u003c/p>","interaction":"\u003cp>A1：拆书家提问设计：以上是我对这个片段的理解和在生活中的运用。下面呢我们分成两个组进行组内分享。我们通过读这个片段，了解了拥抱工具的适用情景和实施方法，那么下面就请大家想想自己有没有经历过类似的情境，比如你教育你家孩子，或是你父母教育你的时候有没有类似的经验讨论一下，请在组内分享，然后请两个代表讲一下，时间是5分钟，现在开始。\u003c/p>\u003cp>学习者案例记录：（1~2人）好，下面请一位小伙伴儿进行分享，时间1分钟。\u003cbr>阿丹分享：分享经验，当孩子睡不着觉时，感觉很焦虑的时候，通过抱抱来缓解孩子的不良情绪，来达到目的\u003cbr>拆书家：孩子睡不着觉的时候产生的焦虑感也是一种不良的情绪，那通过抱抱的形式会让他情绪放松，从而缓解这种焦虑的心态。其实，拥抱也不一见得非得用于亲子教育中，在人们沟通中，彼此双方存在不良情绪的情况下，都可以通过这种情况来缓解双方的不良情绪，拥抱也是一种给对方释放一个善意的信号。\u003c/p>\u003cp>A2：拆书家提问设计：(逐字稿）下面请大家用1分钟的时间写下在未来具体时间段中，如果出现负面情绪时，你如何运用该工具来缓解沟通中存在的不良情绪。比如说你要怎么抱，使用的场景是什么？\u003c/p>\u003cp>小面：在以后和男朋友吵架的时候，会先摸摸对方的头，然后再抱抱对方，这样一是来调节自己的心态，二是同时缓解双方的不良情绪。\u003cbr>\u003c/p>\u003cp>非常好，这位小伙伴儿虽然没有把拥抱这个工具用于亲子管教上，但是活学活用，却把它用于了处理两性关系上，很好地把握了拥抱工具的实质是用于平缓不良情绪的工具，而不一定非得要界定于亲子关系上，另外，用摸摸头和拥抱来共同完成拥抱的环节，正确地做到了有爱有温暖的拥抱。\u003c/p>\u003cp>谢谢大家，今天我的带拆就到这里结束。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1500357511000,"updated_at":1500386680000},{"id":3082,"topic":"鼓励VS赞美","learn_goal":"学会运用鼓励技巧帮助孩子性格及能力发展","remark":"赞美像糖果，可以偶尔使用，但是太多，可能令孩子容易上瘾，容易趋向取悦他人，对“自我价值”的深刻认识和创造不健康。而鼓励，则帮助孩子对自己性格的长处和能力得到发展，培养自信，而不是他信。","level":"TF2-3","duration":30,"status":0,"type":0,"chaishujia":{"username":"金凤","city":"东莞"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是拆书家黄金凤，当孩子做得好时，我们习惯性的赞美是;你真棒，但长此以往，孩子听了太多诸如此类空泛的赞美，并不确定自己哪里做得好哪里要改进，而且会依赖别人的评价，容易他信而不是自信，那么相对于赞美而言，鼓励关键是什么，有什么技巧，实践中要注意什么，接下来会在我们拆书过程中作分享，在拆书前先分成两个组，左边一组右边一组。\r\n【图书介绍】\r\nF:我们今天分享的书名为《行之有效的正面管教工具》，作者甄颖，“正面管教”40年前源于美国，以奥地利心理学家的“个体心理学”理论为基础，由简尼尔森和琳洛特等教育专家完善，是一个专注相互沟通的，体验式的家长教育体系。本书讲述的主要就是如何运用正面管教方法使孩子获得这种能力。\r\nA:本书具体有以下四大优势：\r\n1、工具式编排和案例式分享大幅降低家长接受正面管教的门槛；\r\n2、12个正面管教工具好评如潮非常接地气，；\r\n3、管教故事真实有效；\r\n4、国际化视野角度点评诚恳有力，直指人心。\r\nB:面对日常教育类书籍阅读中，学术类的和带案例讲解类的书，哪类你会更感兴趣？国外的案例和实践过的中国老百姓案例，哪个对你更有借鉴意义？大部分人都会选择","ratings_count":0,"texts":[{"id":5888,"quote":"\u003cp>《行之有效的正面管教工具》第208页\u003c/p>\u003cp>鼓励VS赞美，赞美像糖果，可以偶尔使用，但是太多，可能令孩子容易上瘾，容易趋向取悦他人，对“自我价值”的深刻认识和创造不健康。而鼓励，则帮助孩子对自己性格的长处和能力得到发展，培养自信，而不是他信。\u003c/p>\u003cp>关键态度：事件的“主角”是孩子不是家长。\u003c/p>\u003cp>技巧：\u003c/p>\u003cp>尽量不给孩子贴标签，不拿孩子跟别人比较；\u003c/p>\u003cp>对孩子的行为结果“照镜子”，客观描述孩子值得鼓励的行为和结果；\u003c/p>\u003cp>关注并说出孩子的感受，而不是大人的感受；\u003c/p>\u003cp>指出孩子的小进步（即使再糟糕的情况，也有值得称赞的地方）；\u003c/p>\u003cp>也可以在客观描述孩子值得赞赏的行为后，总结为一两个“标签”词。\u003c/p>","explains":"\u003cp>【I】拆书家讲解引导\u003c/p>\u003cp>\u003cstrong>【亲身案例】\u003c/strong>为了鼓励孩子睡前刷牙的习惯，当孩子自己刷牙时候对孩子说的最多的一句话就是孩子你真棒。这一招一开始对孩子来说非常受用，我一说你真棒，你刷得真好，孩子就会拿着牙刷自己开始刷起来，但是说得多了，孩子好像也没有一开始的时候表现积极，把牙刷给孩子时，有时会提出“妈妈你帮我刷嘛”这种请求，甚至有时累了就会说我不刷然后一个大字躺在床上，怎么哄都不愿意刷，可见，这种泛泛的“你真棒”外在赞美方式未能真正持久驱动孩子的内在动力。\u003c/p>\u003cp>\u003cstrong>【原文拆解】\u003c/strong>原文提到，鼓励重点在于“励”赞美重点在于“美”，前者强调让事件的主角孩子主动积极做出改善的行为，调动孩子自己的内在驱动力，而后者极容易造成过度赞美，导致孩子变成“讨好者”，总是想获得他人的认可，调动的是孩子的外在驱动力，一旦外在驱动力没有了，孩子就没有动力了。\u003c/p>\u003cp>\u003cstrong>【细化原文技巧】\u003c/strong>为了帮助孩子性格和能力获得更客观更持续的发展，我们可以这么尝试运用原文提到的关键技巧去鼓励：1、照镜：客观描述孩子值得鼓励的行为和结果，对其行为或结果照镜子，描述你所看到的，你感受到的，2、共情：关注并说出孩子的感受，是孩子的感受而不是大人的感受，这里重点是观察孩子行为帮助他说出来，让他看到，3、指向：指出孩子的小进步引导新的动作或行为，即使孩子有做得不当的行为，也是可以通过指向式鼓励来解决的，4、标签：将值得赞赏的行为，总结为一两个“标签”词并鼓励继续该该习惯或能力。\u003c/p>\u003cp>\u003cstrong>【意译原文案例】\u003c/strong>以后在培养孩子刷牙习惯的时候，我将结合鼓励四步法尝试以下方式进行鼓励引导1、描述我所看到的孩子自己主动刷牙的行为和结果，孩子今天你主动去拿牙刷来刷牙，还创造左右刷牙方式，你看一下镜子，刚刚是不是这样子左右刷？下门牙都刷得非常干净呢，刷完牙是不是还特别舒服？2、关注并引导孩子说出刷牙要克服的困难及感受，你知道吗，妈妈小的时候刚开始刷牙也不知道怎么刷，而且每天要坚持刷确实不容易，牙齿这么多，要全部刷干净是不是要花费些功夫啊？现在是接近睡觉时间还要刷坚持完牙才睡觉，这个是不是也不容易？3、指出孩子的小进步并作新的引导：你克服困意主动提出要刷牙，而且你自己给自己刷牙，还创造了左右刷的方式，可以演示给妈妈看一下还有哪些好玩的刷牙方式？是一颗一颗刷还是里外刷？4、将值得赞赏的刷牙等行为，总结为一两个“标签”词并为下一次行动作鼓励：孩子尽管你现在有点困了，但你今天仍然拿起牙刷刷牙，这叫“坚持”，尽管妈妈可以帮你刷牙，但你还是自己刷，这叫“积极主动”，孩子你今天创造了左右刷牙的方式，这叫“不断创新”，明天你还会创新怎样有趣的刷牙方法呢……\u003c/p>","interaction":"\u003cp>【A3】促动参与\u003c/p>\u003cp>拆书家提问设计（逐字稿）\u003c/p>\u003cp>【场景】我们刚刚学习了可以鼓励四步法来替代赞美或者指责纠正孩子，现在一起来做一个演练。演练背景是这样子的：孩子从客厅跑到你的房间，手里拿着一张纸，上面是各种彩笔的涂鸦，放在你的面前问你：“画得好看吗？” \u003c/p>\u003cp>现在，两人一组作角色扮演练习，一个人扮演孩子，另一个人扮演家长，请扮演家长的角色运用鼓励四步法来作引导，演练万后再作角色互换。\u003c/p>\u003cp>演练时间3分钟，现在开始，3分钟后，我会选一组来作角色扮演及对话，大家一起观察及听听家长是如何运用鼓励四步法工具，以及孩子是什么反应的。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>（孩子—学员佐旭、妈妈—学员敏君）\u003c/p>\u003cp>孩子:妈妈，你看我画的画。\u003c/p>\u003cp>妈妈:是哦，我看到你今天会用很多颜色了画画了哦，你是在画一座城堡吗？\u003c/p>\u003cp>孩子:是的，是城堡。\u003c/p>\u003cp>妈妈:宝宝，我还看到你画了一个有笑脸的太阳，你很开心吧？\u003c/p>\u003cp>孩子:是啊。\u003c/p>\u003cp>妈妈:妈妈好喜欢你今天的这幅画。你今天画得比昨天好多了，圆圈画得比昨天的要圆呢。\u003c/p>\u003cp>【回应】非常感谢佐旭和敏君的分享，在刚刚场景中，妈妈巧妙地运用了照镜例如“我看到”等方法作鼓励非常好，同时，我们还可以使用标签等方法作鼓励也会收到不错效果，例如说你今天画画非常专心，这叫一心一意。\u003c/p>\u003cp>【小结】通过刚刚拆解及练习，相信大家对鼓励及赞美的区别有一定了解，并通过练习对鼓励四步法照镜、共情、指向、标签加深了印象，希望在接下来与孩子相处中能应用鼓励方法，调动孩子自己的内在驱动力，帮助孩子性格和能力获得更客观更持续的发展。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1498832862000,"updated_at":1498836420000,"ria":true},{"id":3081,"topic":"如何正面引导孩子应对负面情绪以及解决问题？","learn_goal":"学会运用\"积极暂停\"及\"正面语言\"作为正面管教的主要工具","remark":"示范及引导孩子使用\"积极暂停\"及\"正面语言\"方法，引导孩子养成用“积极暂停角”应对自己的负面情绪及采用正面语言思维惯式解决问题。","level":"TF2-4","duration":60,"status":0,"type":0,"chaishujia":{"username":"金凤","city":"东莞"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是拆书家黄金凤，今天我们拆解的主题是积极暂停及正面语言，在拆书前先分成两个组，左边一组右边一组。\r\n【图书介绍】\r\nF:我们今天分享的书名为《行之有效的正面管教工具》，作者甄颖，“正面管教”40年前源于美国，以奥地利心理学家的“个体心理学”理论为基础，由简尼尔森和琳洛特等教育专家完善，是一个专注相互沟通的，体验式的家长教育体系。本书讲述的主要就是如何运用正面管教方法使孩子获得这种能力。\r\nA:本书具体有以下四大优势：\r\n1、工具式编排和案例式分享大幅降低家长接受正面管教的门槛；\r\n2、12个正面管教工具好评如潮非常接地气，；\r\n3、管教故事真实有效；\r\n4、国际化视野角度点评诚恳有力，直指人心。\r\nB:面对日常教育类书籍阅读中，学术类的和带案例讲解类的书，哪类你会更感兴趣？国外的案例和实践过的中国老百姓案例，哪个对你更有借鉴意义？大部分人都会选择后者，而本书恰好戳中这些痛点，满足我们家长的喜好，正面管教工具一目了然，家长们不但从书中学到易学实用的方法和工具，还可从真实的具有言传身教效果的实际案例中模仿演练，解决孩子睡觉吃饭拖拉，不听指令、轻易放弃等日常问题，帮助家长找到引","ratings_count":0,"texts":[{"id":5887,"quote":"\u003cp>\u003cstrong>R\u003c/strong>\u003cstrong>片段一《行之有效的正面管教工具》第68页 \u003c/strong>\u003c/p>\u003cp>发生负面情绪时，从引起负面情绪的场景或事件暂时离开，在自己觉得舒适的环境里自行调节情绪。这个舒适的空间，可被称为“积极暂停角”\u003cbr> 关键态度：感觉更好，就会做得更好\u003cbr> 技巧：\u003cbr> 解释“积极暂停角”安抚情绪的作用，不是用作惩罚，只是安抚情绪；\u003cbr> 让孩子选择、布置、起名，孩子参与越多越好；\u003cbr> 自己率先使用，让孩子看到效果，要告诉孩子你“会回来”。\u003c/p>\u003cp>\u003cstrong>R\u003c/strong>\u003cstrong>片段二《行之有效的正面管教工具》第46页\u003c/strong>\u003c/p>\u003cp>把正面管教的思维和语言教给孩子，孩子就养成正面思维惯式，说出正面语言。典型的正面语言是温和而坚定的，着眼于解决问题。解决的过程强调孩子参与的主动性。本章的正面语言包括了“提前说”，“暗号”。\u003cbr> 关键态度：坚定，而不是强硬。\u003cbr> 技巧：\u003cbr> 具体而清晰的语言，有条件的许可；孩子明白的暗号或手势；家长知道接下来正确的事情是什么，并且做；\u003cbr> 提前告知，让孩子知道接下来要发生的事情；\u003cbr> 不是模糊笼统的命令，而是清晰具体的指令； \u003cbr> 发散性有创意的思维，多和孩子“头脑风暴”；\u003cbr> 使用“你一……就可以……”句式，让孩子看到自己的行为的积极结果；\u003cbr> 使用非语言表达方式，例如手势、暗号等。\u003c/p>","explains":"\u003cp>\u003cstrong>片段一【I】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【亲身案例】\u003c/strong>我们家孩子最近出现生气会打人现象，前几天带尼欧去哥哥家玩，在玩耍前特别强调游戏规则，谁先拿到的玩具先谁先玩，如果要玩对方的玩具要征求对方同意，两个小朋友都说好，然后开始开心地玩起来，前五分钟非常友好，五分钟后两个人就扭在一起抢一个白色的捞鱼玩具，尼欧很生气就拍了哥哥的头，我赶紧把尼欧拉到一边。\u003c/p>\u003cp>\u003cstrong>【负面一般做法】\u003c/strong>我当时因为尼欧动手打人感觉非常生气，说话音量提高：“不是说过谁先拿到玩具谁先玩，要玩别人的玩具要征得别人的同意吗？你怎么能随便打人？打人是很疼的。你打了哥哥，一会他不跟你玩了怎么办，尼欧扭过头不看我，我把尼欧拉到墙角继续说：你站在墙角冷静一下先。尼欧假装站一下就准备走开，我拉他回去继续站，他开始哭闹起来。虽然尝试使用冷静角，但是并未起作用，这让我觉得非常挫败。\u003c/p>\u003cp>\u003cstrong>【这样做的坏处】\u003c/strong>当时我并未控制好自己的情绪，因而态度是指责的，处理事情是主观不理智的，最终结果是孩子自己觉得委屈、不愿意跟我沟通，而我也觉得非常沮丧。\u003c/p>\u003cp>\u003cstrong>【拆页行动建议】\u003c/strong>阅读原文片段后发现，现实中，处理事情之前先处理心情有多重要，让自己或者孩子感觉先好起来，才能做得更好，而积极暂停角,就是让感觉好起来的极好方式。\u003c/p>\u003cp>\u003cstrong>【把刚才例子变成正面例子】\u003c/strong>如下次再遇到这种情况我会这么做：孩子，妈妈现在心情不好没法控制自己的情绪，需要去冷静太空充电一下，你可以选择回你自己的冷静太空充电，或者站在这里等一下，妈妈充完电后会回来……现在经过充电感觉好多了，可以跟妈妈讲讲你们刚刚发生什么事情吗？你的意思是哥哥不想跟你交换那个玩具，你很生气是吗？如果是别人不跟我交换分享玩具，我也会非常生气的，刚刚妈妈生气的时候怎么办？如果下次生气的时候你建议怎么办？对啊也可以到冷静太空充电一下，刚刚你提出交换玩具但哥哥没同意，你还有别的办法么？例如说玩别的玩具或找其他大人帮忙？刚刚你拍了哥哥的头，他很疼也很难过，我们现在去跟他说对不起，抱抱他安慰他，好吗？\u003c/p>\u003cp>\u003cstrong>【预防异议的讲解】\u003c/strong>这时有的父母会有疑问，孩子无理取闹的时候，抗拒暂停角怎么办。这时需检视一下如果使用的暂停角是惩罚孩子的负面暂停角，就需要调整为让孩子感觉会变好的积极暂停角。还有父母说孩子哭闹场不在家里没有暂停角怎么办，积极暂停角是一个方法，没有固定地方的时候可约定其他积极暂停的方法例如深呼吸或爱心手势等动作或仪式。\u003c/p>\u003cp>\u003cstrong>【细化原文行动建议的步骤】+【根据原书案例脉络给出更贴近实际例子】\u003c/strong>为了能更好地应用原文片段知识点，我们将“积极暂停角”简单概括为四步法：1、父母示范+反复实践。例如我会先宣布书房书桌是我的冷静角，每次情绪不好时候先到书桌前抄书或看书2、让孩子创建+布置+命名“积极暂停”活动区域，由孩子决定，无论看书写字画画听音乐玩玩具等方式都可以，只要是让他感觉好即可；3、约定启用时间及暗号，情绪不好时候启用暂停角，如果孩子忘记了就用暗号提示他，例如说眨眨眼，深呼吸状，爱心手势等；4、约定问题闭环。例如主动找你说话，开始微笑示好时，就可以引导孩子自己处理或共同找办法解决问题。\u003c/p>\u003cp>接下来我们做&quot;正面语言&quot;的分享，大家请看下打印好的原文片段\u003c/p>\u003cp>\u003cstrong>片段二\u003c/strong>\u003cstrong>【I】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【亲身案例】 \u003c/strong>\u003cbr> &nbsp;有一天晚上孩子20:30上床后开始喝牛奶听故事，20分钟后，我到房间一看牛奶还没喝完，就开始催促：没喝完不能听妈妈讲故事哦，快点喝。孩子依旧慢慢喝牛奶，好不容易牛奶喝完了准备刷牙，孩子说要讲故事不刷牙，我说刷完牙才能讲故事，不刷牙牙齿会有虫子咬会很痛，赶紧刷牙。哄了半天，孩子磨磨蹭蹭敷衍着刷牙，这些流程终于结束了我赶紧准备关灯睡觉，孩子大吼，我不要睡觉，我还要讲故事，我看时间超过22:00就直接关灯说：关灯了再讲故事，结果孩子哭得更凶了，我当时那一肚子的气简直要爆炸了。\u003cbr> \u003cstrong>【负面一般做法】\u003c/strong>\u003cbr> 遇到孩子睡前磨磨蹭蹭的时候我很容易焦虑、着急，态度是不耐烦的，语气是责备的，音量是提高的，语言是负能量的，这时候孩子往往是委屈的、愤怒的、对抗的，结果就是大人孩子整个都不好了。\u003cbr> \u003cstrong>【这样做的坏处】\u003c/strong>\u003cbr> 父母焦虑着急时传递的不耐烦的眼神、粗鲁的肢体动作、负面语言会伤害孩子，让孩子觉得自己很糟糕，孩子会脾气暴躁、变得自卑，没有主见。\u003cbr> \u003cstrong>【拆页行动建议】\u003c/strong>\u003cbr> 正面引导及传达很重要一种方式是坚定的语言及肢体传达，包括具体而清晰的语言，坚定的眼神，明确的肢体暗示，按照原文提示，可以通过提前说（清晰而具体指令，例如“你一……就可以……”），暗语（多和孩子“头脑风暴”使用手势、提示物等暗语）等方式实现正面语言传达。\u003cbr> \u003cstrong>【把刚才例子变成正面例子】\u003cbr> \u003c/strong>下次我可以这么说：孩子，现在不想睡觉是不是因为想要妈妈陪你多一会啊，妈妈也想多陪你一会，下次如果你想妈妈多陪你一会，你做一个暗号或者手势，用什么暗号好呢？我们猜拳决定讲2个还是3个故事好吗，你早点将牛奶喝完牙齿刷完，我们就可以早点开始讲故事，看这个时钟，只要8:15前刷完牙坐到床上，就可以多讲一个故事哦，只要8：50前关灯我们还可以多讲一个故事哦，这样加起来就有5个故事了，今天想不想讲5个故事啊，那现在洗完澡要干嘛呢，对，喝牛奶和刷牙，下次喝牛奶时间我们用什么暗号互相提示呢，刷牙时间希望我们又用什么暗号互相提示呢……。\u003c/p>\u003cp>\u003cstrong>【预防异议的讲解】\u003c/strong> \u003cbr> 这时候有父母提出异议，说好了讲几个故事就几个故事，要坚持原则不能讲条件，否则会让孩子会得寸进尺，助长其“不良行为”，殊不知，孩子的“不良行为”其实是他为了寻求关注做出的与年龄相仿的行为，并不会意识到这是一个错误的观念，我们重点是用正面语言替换负面语言作引导，例如将不要推不要抢的暗号变成征求对方同意或者交换玩具的暗号，将生气打人暗号变成生气时候打沙包暗号。\u003cbr> 很多父母会有疑问，我之前也曾经与孩子制定暗号，但是执行一段时间后，用了没几次就没效果了。为什么会这样呢，原因在我们父母，孩子表达暗号的时候，父母是否有关注并回应这个行为？例如孩子摆出心形造型想要获得父母关注时，父母是否对孩子的暗语作积极回应，例如回应心形造型？\u003cbr> 还有父母提出困惑，当错误发生时候，孩子本能会逃避和解释，根本听不进去，更别说暗语了。这时候我们要做的，是给孩子创造一个“情绪安全”的环境，给予孩子时间、空间、理解，信任及接纳孩子，待孩子情绪稳定后，引导孩子用正面语言表达及找到更好的解决办法，\u003cbr> \u003cstrong>【细化原文行动建议的步骤】+【根据原书案例脉络给出更贴近实际例子】\u003c/strong>\u003cbr> 我们现在将原文提到正面语言方法归纳为约定规则、声明规则、提醒规则三步曲 1、头脑风暴约定规则时，这里不限定非得要特地家庭会议才能头脑风暴，而是随时随地都可以约定，要多引导孩子作发散性有创意的思维，内容有加分项及减分项，引导孩子向更积极的行为发展；例如“你一……就可以……”2、提前说声明规则时，强调说的是清晰而具体指令，不是模糊笼统的命令，让孩子明白接下来要做的事情具体是什么，并且是马上要执行的，例如说玩之前说好谁先拿到玩具谁先玩；3、暗语提醒规则时，这里强调是由孩子发起的暗语，大人要对这个暗语进行回应，提示的暗语含义是有积极正面效果的，包括手势、动作、暗号、提示物品等，例如用心形手势代表“我理解你，我依然爱你”。&nbsp;\u003c/p>","interaction":"\u003cp>\u003cstrong>片段一\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1】激活经验\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【显像提问法】\u003c/strong>为了更好地催化应用知识点，我们现在想象一下那些曾经让你抓狂的场景，例如当你又累又热的时候孩子提出要抱抱，；当你赶着上班时候，孩子各种磨磨蹭蹭不出门……或者其他场景，你是怎么处理的？\u003cstrong>【反思加工】\u003c/strong>你觉得哪些做得好，哪些要改进。时间一分钟。\u003c/p>\u003cp>学习者案例记录：\u003cbr> 学员敏君：记得我们孩子小时候吃饭特别慢，有时候吃一口嚼半天都不吞下去（当时孩子快上小学了，外婆怕孩子饿会追着喂饭），看到这些场景让我非常抓狂，快点来吃啊，不吃一会没得吃啦，一会揍你一顿啦 ，现在回想起来，与孩子沟通的态度需要改进一些，孩子不想吃饭一定有他的原因，但是我们只是看到表面上的，没有看背后的原因，以后应该自己先深呼吸冷静下来，然后再好好地跟孩子聊一聊背后的原因以及接下来的解决方案，整个过程让他自己参与进来并且达到让他主动积极吃饭的效果，下次会先深呼吸，通过冷静角让自己冷静下来。\u003c/p>\u003cp>【回应】非常好的分享，刚敏君提到遇到孩子不吃饭的场景当时的反应是非常抓狂，用指责的方式跟催促孩子吃饭，确实，遇到孩子的这些半天没吃完一口的场景，确实很容易让人着急，也会导致我们语言、肢体上的不耐烦及呵斥，此时情绪控制非常关键，刚敏君也提到了一些非常好的方式，包括深呼吸冷静角等\u003c/p>\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>\u003c/p>\u003cp>刚刚提到冷静角及情绪暂停角，你将如何应用刚学到的暂停四步法来面对刚刚遇到抓狂场景，让自我感觉变好，并找到解决方法，请写在便签上。\u003cbr> 学习者案例记录：\u003c/p>\u003cp>学员敏君：如果再看到小孩这种总是不吃饭让我抓狂的情况，我会跟孩子说：现在妈妈很生气，我现在不想跟你生气，我先去小书房冷静角坐一坐冷静一下，孩子很可能会跟着去他自己的史努比冷静角冷静一下，等感觉好些了再出来开始吃饭，并等饭后他感觉好了再一起聊聊下次遇到这种情况该怎么解决。\u003c/p>\u003cp>【回应】非常感谢敏君分享，在刚刚案例过程中，敏君较好地使用了示范、与孩子一起创建命名、约定下次使用规则等技巧，应对抓狂情绪及作积极暂停引导，\u003c/p>\u003cp>【小结】各位已经对父母示范、让孩子创建命名、约定使用暗号，约定问题闭环等方法有了一定的了解并通过演练加深了印象，在这个积极暂停的过程特别注意让我们包括大人和孩子感觉更好后，才能更好地找到解决办法。积极暂停的分享就暂告一段落，谢谢大家。\u003c/p>\u003cp>\u003cstrong>片段二\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A3】促动参与\u003c/strong>\u003c/p>\u003cp>【给出具体场景】+【设计的指令清晰】+【小组讨论出角色扮演】\u003cbr> 我们刚刚学习了正面语言传递三步骤第一是头脑风暴——约定规则，第二是提前说——声明规则，第三是暗语——提醒规则，现在一起来做一个演练。爸爸和妈妈有个重要紧急的事情正在沟通，孩子原来在旁边玩玩具，看见大人在说话就多次跑过来多次打断大人聊天\u003cbr> 孩子问，妈妈/爸爸，你跟我玩玩具嘛\u003cbr> 妈妈/爸爸：……现在，两人一组作角色扮演练习，一个人扮演孩子，另一个人扮演家长，请扮演家长的角色运用正面语言传递三步骤来作引导，演练完后再作角色互换。演练时间3分钟，现在开始，3分钟后，我会选一组来作角色扮演及对话，大家一起观察及听听家长是如何运用正面语言传递三步骤技巧，以及孩子是什么反应的。\u003cbr> 学习者案例记录：\u003cbr> 第一次演练：晓勤—孩子；敏君—妈妈\u003c/p>\u003cp>孩子：妈妈你快点过来跟我玩玩具，这个玩具很好玩\u003c/p>\u003cp>妈妈：哎呀宝贝我正在跟你爸爸忙着呢，请稍等稍等\u003c/p>\u003cp>孩子：可是我很想跟你玩，你看这个可以飞起来飞得很高，你都没看……\u003c/p>\u003cp>妈妈：那你等两分钟好不好，你看那个钟，走完两圈我就会跟你玩，走完两圈跟妈妈伸出手指：耶这样，妈妈就知道时间到了\u003c/p>\u003cp>孩子：好无聊啊，妈妈再陪我玩一会，现在好像已经走了两圈了\u003c/p>\u003cp>妈妈：这么快转完了，我们的暗号呢\u003c/p>\u003cp>孩子：我没有暗号，你只是让我看着钟转而已啊\u003c/p>\u003cp>……\u003c/p>\u003cp>【回应】刚刚演练过程中，我们发现妈妈说的耶的手势暗号是妈妈自己想的，不是孩子想的，孩子对这个暗号就没有特别概念，更别说遵守暗号，这个暗号建议由执行者孩子自己创建，另外暗号如果是提前约好的话就更好，遇到紧急情况的时候就可以用上，可以避免孩子不承认这个暗号的场景。刚有伙伴提出这个提到暗号，但当时没有约定暗号怎么办，这时候可以等大家情绪都好了后再找个合适时机约定一个再次面对该场景下的暗号\u003c/p>\u003cp>现在请针对第一次演练情况，作一次优化后的升级版演练。\u003c/p>\u003cp>第二次演练：晓勤—孩子；敏君—妈妈\u003c/p>\u003cp>孩子：妈妈妈妈，我想玩这个玩具，你陪我一起玩吧\u003c/p>\u003cp>妈妈：我跟你爸爸正在忙着一件很重要的事情，你能否稍微等一等呢？\u003c/p>\u003cp>孩子：我不想等，你看这个多好玩啊，这个飞机一下子就飞出去好远，多好玩，你就陪我玩一会嘛\u003c/p>\u003cp>妈妈：我知道你现在很想跟妈妈一起玩，你只要给妈妈三分钟时间，妈妈一定陪你玩个够\u003c/p>\u003cp>孩子：那三分钟到了怎么办呢\u003c/p>\u003cp>妈妈：三分钟到了你就过来提醒我，扯一扯我的衣角，记不记得你平时怎么提醒妈妈的\u003c/p>\u003cp>孩子：我喜欢扯一扯你的衣角\u003c/p>\u003cp>妈妈：如果你扯一下你的衣角，我觉得可以陪你玩的话我也扯一下你的衣角，你看一下时间三分钟可以吗？\u003c/p>\u003cp>孩子：那三分钟我怎么办呢，我自己玩好无聊我不想自己玩\u003c/p>\u003cp>妈妈：如果是这样的话你自己能不能想想办法呢\u003c/p>\u003cp>孩子：我自己想办法啊\u003c/p>\u003cp>妈妈：你只要等三分钟，三分钟之后我跟你一起玩三个小时\u003c/p>\u003cp>孩子：那我自己去玩吧，妈妈三分钟之后我过来找你哦\u003c/p>\u003cp>妈妈：好的一言为定啊\u003c/p>\u003cp>【回应】感谢经验演绎，这次敏君很好地使用了包括头脑风暴、提前说、暗语等技巧，并用了一个很好的引导方式，“你一……就可以……”引导孩子向更积极的行为发展；特别在孩子出现“不良行为”的时候我们可以跟孩子玩一种“换一个方式”的游戏，例如用生气时跺跺脚，打沙包代替生气时打人，并用暗语进行提示。\u003c/p>\u003cp>【A2】催化应用\u003c/p>\u003cp>【分步催化指令清晰（显现提问引导的场景指向未来会遇到的，学习者要加工的是未来那个场景中如何用）】\u003c/p>\u003cp>现在场景是打人孩子情绪都已经稳定下来了，为避免孩子下一次的“不良”打断讲话行为，你讲如何应用刚学到的头脑风暴+提前问+暗语方法，达到用正面语言及方法引导孩子学会接纳和疏导自己的情绪及找到解决方法效果，请写在便签上。一会请一个小伙伴来跟我们分享\u003c/p>\u003cp>学习者案例记录\u003c/p>\u003cp>学员晓勤\u003c/p>\u003cp>假如你正在看奥特曼打怪兽的电视的那一刻，妈妈突然把电视关掉，你会觉得怎么样？对，妈妈知道这样会让你感觉非常不舒服，你会很生气，那你想想上次爸爸妈妈在谈一个很重要的事情的时候，你突然冲过来说要妈妈陪你玩玩具，其实妈妈当时跟你感受是一样的，妈妈当时其实很想先处理跟爸爸正在谈的那件事情，那下一次如果妈妈和爸爸，或者其他的人正在谈话，而你想跟妈妈玩的时候，你觉得怎么提示妈妈比较好，或者做一个什么动作能提示一下妈妈。\u003c/p>\u003cp>&nbsp;【回应】刚刚晓勤很完整地使用包括头脑风暴+提前问+暗语三部曲去传递正面语言及引导孩子学会找到解决办法，在具体方法应用上也非常灵活，包括说头脑风暴时候使用突然关掉欧特曼电视剧的感受，去作换位思考共情方式，让孩子体验一下被打搅的感觉，这些方法都非常好。\u003c/p>\u003cp>\u003cstrong>【结语--强调核心要点/呼应讲解内容等】\u003cbr> \u003c/strong>人生不可能一帆风顺，我们能送给孩子最宝贵的东西就是带领孩子一起去体验，情绪失控时会积极暂停，遇到问题时永远积极正对，运用正面语言及积极暂停方法永远都不会太早或太晚，本次分享到此结束，感谢大家分享参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":true}}],"created_at":1498832404000,"updated_at":1498837290000,"ria":true},{"id":3079,"topic":"如何引导教育孩子，让孩子学会自主？","learn_goal":"学员学会引导孩子制作有效的惯例表，还孩子自主权","remark":"关键是找到需要制作惯例表的时间段，通过启发式提问和“头脑风暴”，引导孩子想出时间段内的事情和内容；引导孩子将内容排列出顺序；可以用照片、画画、贴纸等各种方式完成制作；与孩子参与，越多越好。","level":"TF2-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"金凤","city":"东莞"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是拆书家黄金凤，有什么办法可以避免混乱的学习或者生活工作状态，有人脑海中立刻想到了一种办法，就是做计划，这是个好办法，学生上课有课程表，工作时候有工作计划，那么针对幼儿时期孩子是否有一种避免失控局面的方法，有专家提出思考，可以建立一种习惯规律养成表也就是惯例表，那么现在新的问题就来了，惯例表的制作是大人做还是孩子做？怎样的惯例表才是对孩子真正有效的惯例表？在接下来的拆书中会分享如何引导及制作这种帮助孩子自律的惯例表。在拆书前先分成两个组，左边一组右边一组。","ratings_count":0,"texts":[{"id":5883,"quote":"\u003cp>《行之有效的正面管教工具》第104页\u003c/p>\u003cp>本章运用惯例表作为正面管教的主要工具。\u003c/p>\u003cp>含义：惯例表，就是把日常应有的行为习惯，通过书写、画画等方式表现出来。它还有不同的名字:日程表，规律表等等。\u003c/p>\u003cp>关键态度：给以孩子掌握自己生活的权力。\u003c/p>\u003cp>技巧：\u003c/p>\u003cp>找到需要制作惯例表的时间段；\u003c/p>\u003cp>通过启发式提问和“头脑风暴”，引导孩子想出时间段内的事情和内容；\u003c/p>\u003cp>可以用照片、画画、贴纸等各种方式完成制作；\u003c/p>\u003cp>让孩子参与，越多越好。\u003c/p>","explains":"\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>F:\u003c/strong>我们今天分享的书名为《行之有效的正面管教工具》，作者甄颖，“正面管教”40年前源于美国，以奥地利心理学家的“个体心理学”理论为基础，由简尼尔森和琳洛特等教育专家完善，是一个专注相互沟通的，体验式的家长教育体系。本书讲述的主要就是如何运用正面管教方法使孩子获得这种能力。\u003c/p>\u003cp>\u003cstrong>A:\u003c/strong>本书具体有以下四大优势：\u003cbr> 1、工具式编排和案例式分享大幅降低家长接受正面管教的门槛；\u003cbr> 2、12个正面管教工具好评如潮非常接地气，；\u003cbr> 3、管教故事真实有效；\u003cbr> 4、国际化视野角度点评诚恳有力，直指人心。\u003cbr> \u003cstrong>B:\u003c/strong>面对日常教育类书籍阅读中，学术类的和带案例讲解类的书，哪类你会更感兴趣？国外的案例和实践过的中国老百姓案例，哪个对你更有借鉴意义？大部分人都会选择后者，而本书恰好戳中这些痛点，满足我们家长的喜好，正面管教工具一目了然，家长们不但从书中学到易学实用的方法和工具，还可从真实的具有言传身教效果的实际案例中模仿演练，解决孩子睡觉吃饭拖拉，不听指令、轻易放弃等日常问题，帮助家长找到引导孩子自信，自律，拥有强大内心力量的成长途径。\u003c/p>\u003cp>【I】拆书家讲解引导\u003c/p>\u003cp>\u003cstrong>【亲身案例】\u003c/strong>为了培养孩子喜欢运动，音乐，阅读，自律等习惯，我曾经给孩子做过这么一个惯例表：7：30起床后磨耳朵，13：00午休,20：30睡前音乐音律培养，20：30上床喝牛奶讲故事,21：00关灯，饭前饭后洗手，早饭晚饭半小时后的运动,睡前刷牙,在马桶拉臭臭，回家后先换鞋后洗手，谁先拿到的玩具谁先玩\u003c/p>\u003cp>\u003cstrong>【案例失败结果】\u003c/strong>然而，尽管这个惯例表已经做得非常简单易行，但实际是有些规则并不受孩子待见，例如睡前刷牙，到了规定时间，孩子找各种借口不配合刷牙甚至拒绝刷牙，有时候睡前放音乐孩子说我要听故事，回到家有时候还是会喜欢穿着鞋子直奔游戏区……\u003c/p>\u003cp>\u003cstrong>【原文拆解】\u003c/strong>阅读原文后发现，这个计划是我的计划而不是孩子自己的计划。根据原文片段，属于孩子的惯例表应该让孩子更多地参与制作惯例表的过程，通过启发式提问和“头脑风暴”，引导孩子想出时间段内的事情和内容并作排序，最后用一些有趣的如画画、照片等方式可视化。这里强调给予孩子掌握自己生活的权力，帮助他们建立自律的性格。\u003c/p>\u003cp>\u003cstrong>【拆页行动建议】\u003c/strong>接下来我会这么跟孩子一同优化这个惯例表：“NEO想一想，我们白天和晚上都要做哪些有趣的事情啊,除了洗澡后喝牛奶讲故事，还有哪些好玩的事情哈，对啊，饭前要搓泡泡洗手，吃完饭后接下来我们要做什么呢，对啊，饭后要漱口，另外，桌子上面的照片有没有你觉得好玩事情呢，哦，原来还有回家后要换小猴子拖鞋要洗手，那是先换鞋还是先洗手？哦，对，还有睡前用火车牙刷刷牙，用大象马桶拉臭臭……哇，NEO的一天要做这么多有趣的事情，太开心了，我们一起来将这些有趣的事情排个队，然后粘在大白纸上吧，哇，NEO粘得非常认真，这个惯例表被NEO粘得像长长的托马斯一样酷，现在，我们手脏了怎么办，手洗完之后我们接下来要干什么事情呢……”在这个行动中，我与孩子一起“头脑风暴”，运用启发式提问一步步引导孩子自己想出每天要做的事情，提前将相关动作照片打印出来，给孩子作联想思考，并且每做一件事情就来到惯例表面前指给NEO看，并鼓励他引导他想出下一个行动动作。从计划要执行每个环节都让孩子参与，让孩子自己去制定规律，执行规律，监测规律。\u003c/p>\u003cp>\u003cstrong>【预防可能的异议】\u003c/strong>\u003c/p>\u003cp>大家有部分人可能会觉得孩子这么小，要求这么多，孩子多累啊，殊不知，每天都发生各种各样的新鲜事，大大小小的事情都会在不断变化中，建立惯例表，让孩子有规律的生活，孩子反而觉得更有安全感，并且让孩子早点参与制作他们的惯例表，会提高他们的归属感和成就感，如果孩子很小没关系，你试试看，在实践中你会找到答案的；\u003c/p>\u003cp>还有一些人会觉得太麻烦了，生活不是应该随意随性些么，来场说走就走的旅程不是挺好的么？殊不知，对孩子而言，容易理解执行及灵活的惯例表更利于孩子成长，一切都是可预知的，遇到问题习惯有明确的指引，孩子才不会对未来发生的事情产生担心和恐惧；\u003c/p>\u003cp>更有一些人疑虑，惯例表心里有数就好，没必要用这么正规的方式呈现吧，就算做出来了，没有做到那岂不是白费劲啦，惯例表可视化会让孩子更有成就感并且可以时常提醒孩子，做出惯例表计划但实际没有做到也没有关系，不断尝试不断调整不断摸索并不断坚持，孩子内心有个强大的驱动力，只要我们给孩子自由、信任和方法，孩子会比大人更加自律，你会收获更多惊喜。\u003c/p>","interaction":"\u003cp>【A2】催化应用（分步骤化1）\u003c/p>\u003cp>【拆书家提问设计（逐字稿）】孩子晚上不想睡觉、早上不想起床，想一直听很多很多的故事，想吃某样食物但不想洗手，回家后不换鞋直接往里走，……请回想一下，哪个场景让你感觉特别无力，特别疲惫，特别失控或者无可奈何，当时是在什么背景下发生，孩子的反应具体是怎样的，请在小组内分享一下。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学员晓勤：我家孩子晚上睡前很喜欢跟我一起读书、听故事，往往到了睡觉时间，还不肯结束，一直要求我继续读书。而我就觉得很焦虑，担心第二天起不来。而孩子却一直在要求读书、讲故事，没有联想第二天的事情。\u003c/p>\u003cp>非常感谢晓勤分享。\u003c/p>\u003cp>【A2】催化应用（分步骤化2）\u003c/p>\u003cp>【拆书家提问设计（逐字稿）】针对您要引导其养成的规律习惯目标，结合刚刚提到的场景以及未来可能会遇到的状况，请想一想，将如何应用刚刚学到的制作惯例表方法，引导孩子自主制定规律表并养成某习惯，请简要写在便签上，一会请一两位伙伴分享一下。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学员许晓勤：\u003c/p>\u003cp>我计划运用片段教的这种办法，让孩子跟我一起来制作惯例表：\u003c/p>\u003cp>首先，让孩子来参与，用引导式提问，问他每天我们必须要做的事情有哪些？先列出来。或许工作日和周末也有不同呢。\u003c/p>\u003cp>其次，再与孩子讨论，除了必须做的这些事情还有没有其他好玩、有趣的事情可以做呢？再列出来添加进去。\u003c/p>\u003cp>再次，让孩子参与到执行中。每天跟孩子一起来执行，如果发现惯例表有跟实际不相符的，可以再讨论和调整。\u003c/p>\u003cp>非常感谢晓勤分享，晓勤很好应用了启发式提问及与孩子一起头脑风暴，并鼓励孩子主动参与整个过程，这些技巧都应用得非常好。\u003c/p>\u003cp>\u003cstrong>【小结】\u003c/strong>相信大家已经明白惯例表将可能带来的惊喜，并且通过刚刚的练习学会怎么应用“找契机、启发式提问和头脑风暴、引导排序、有趣呈现、让孩子参与”等技巧，引导及与孩子一同制作属于孩子自己的惯例表，让孩子更有安全感，让孩子更有自律\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1498817251000,"updated_at":1498817251000,"ria":true},{"id":3078,"topic":"如何正面引导孩子以达到教育孩子目的？","learn_goal":"学员能利用“共情过程”的两个步骤引导孩子，达到教育孩子的目的","remark":"首先现场介绍自己准备拆的书《行之有效的正面管教工具》，让大家阅读学习书本P16原文片断；讲解原文片断，拆分成几个小组，并分组分享过往经验，激活学习者学习经验；让大家用1分钟在便签纸上写下各自的应用和行动步骤，催化学习者的应用，让学习者掌握及联系辨认感觉+准确语言表达的共情过程。","level":"TF1-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"金凤","city":"东莞"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好我是今天拆书家黄金凤，很高兴大家来到我们拆书现场.本次拆书目标是掌握共情关键点，并学会使用“共情过程”的两个步骤引导孩子，达到教育孩子的目的，我们在拆书前先成两个小组，前面的几位小伙伴一个小组，后边的小伙伴为一个小组，一会儿我们会按照分组进行讨论。","ratings_count":0,"texts":[{"id":5881,"quote":"\u003cp>《行之有效的正面管教工具》第16页&nbsp;\u003c/p>\u003cp>“共情”是心理学术语，又叫同感、同理心。共情的过程是：\u003c/p>\u003cp>一、辨认孩子的感觉，包括正面感觉和负面感觉；\u003c/p>\u003cp>二准确地用语言表达出来。请大家看微信,看完的小伙伴请示意。\u003c/p>","explains":"\u003cp>\u003cstrong>图书介绍：\u003c/strong>\u003c/p>\u003cp>我们今天分享的书名为《行之有效的正面管教工具》，“正面管教”体系40年前源于美国，以奥地利心理学家的“个体心理学”理论为基础，由简尼尔森和琳洛特等教育专家完善，是一个专注相互沟通的，体验式的家长教育体系。本书按照家长学习偏好，以11个深受中国家长欢迎的代表性工具入手，用家长真实案例来介绍正面管教方法和理念。工具式编排和案例式分享大幅降低家长接受正面管教的门槛。让正面管教可以帮助到更多家长。作者甄颖，美国认证“正面管教讲师”，简尼尔森亲导中国讲师，其微博上的自我介绍是“做想给、会给孩子自由、尊重、权力的妈妈”。 \u003c/p>\u003cp>\u003cstrong>【I】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【拆页讲解】\u003c/strong>本片段主要强调共情的过程首先辨认孩子正负面的感觉，这里强调家长要全盘理解和接纳并认可孩子出现的这种感觉，然后才能引导孩子准确表达或引导孩子说出自己的希望。无论是正面的情绪还是负面的情绪，无论是好的行为还是坏的行为，情绪本身是没有对错之分，如果先入为主，认为孩子不可理喻，认为孩子不需要这种矫情的共情，那自己就带着某种色彩看孩子，自然就无法辨认、接纳和认可孩子。\u003c/p>\u003cp>\u003cstrong>【亲身案例】\u003c/strong>现在这里分享我自己的一个案例，我们家孩子不喜欢在马桶上拉臭臭，有几次在孩子准备拉臭臭时候，专门跑去将孩子的小马桶拿过来，孩子推手说不要。我就各种哄，说蓝色的马桶多有趣啊之类的，孩子非常生气将马桶扔开，甚至还大吼走开。当时我想，这孩子咋这么倔……。现在细想一下，孩子当时真实感受是，他就是不习惯也不喜欢用这马桶，而我却只是一味强调孩子你应该喜欢和使用这个马桶，当时我并未去深入辨认及理解孩子的感受，也没有接纳及认可孩子不喜欢马桶的这个感觉，更没有引导孩子准确表达或引导孩子说出他的希望。\u003c/p>\u003cp>【\u003cstrong>正面例子优化\u003c/strong>】基于原文提到的辨认和语言表达的两个关键步骤，下次孩子拒绝在马桶拉臭臭时，我会尝试以下步骤共情，蹲下来温和地看着孩子并对他说“你不喜欢在马桶拉臭臭是不是因为坐在上面不舒服？还是因为这个马桶不好看？你在拉臭臭的时候，不希望妈妈打搅你对吗？你知道吗，如果你在客厅里面拉臭臭会把客厅的花都熏臭了，把客厅里你爱吃的葡萄也熏臭了，怎么办？巧虎最喜欢在哪里拉臭臭哈，快看，原来巧虎喜欢在小马桶上拉臭臭，那你喜欢在小马桶还是大马桶上拉臭臭……”\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】激活经验\u003c/strong>\u003c/p>\u003cp>接下来请各位伙伴想一个你在生活中经历过失败共情案例，在小组内作分享，时间是5分钟。\u003c/p>\u003cp>刚刚大家的讨论非常激烈，下面请一个小伙伴分享下自己关于共情的失败案例。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学员晓勤：前段时间，因为计划与孩子分房睡觉，也折腾过一段时间。我在书上了解到，孩子长到适龄学童年纪时，最好是与父母分房睡觉，书中列举了很多好处。回到家，我就跟儿子说：“宝宝，今天开始，我们要分房睡了，你要回去你的房间了。”儿子听了，一脸不情愿，说：“我不要，妈妈在哪里睡觉，我就在哪里。”现在想来，还真的是有点不管不顾啊。我就硬是把小孩推回他的小房间，结果，每天晚上大家都睡不好。\u003c/p>\u003cp>非常感谢小伙伴们分享的关于共情的失败案例。\u003c/p>\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>\u003c/p>\u003cp>请各位伙伴根据刚分享的失败案例，应用片段提到的辨认和表达两个方法去作共情，并用便签写下你计划的可操作的步骤，时间是1分钟。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学员晓勤：\u003c/p>\u003cp>这个片段提供了一个比较好的办法来解决我上述的分房问题。我想试着用这套方法来看看效果。\u003c/p>\u003cp>首先，辨认孩子的感觉。孩子也是一个独立的人、有自己的思想，我们不可以无视他的感觉，无论这种感觉是正面的还是负面的，因为这种感觉是真实存在的，我应该要去辨认它，而不是忽视它。我想尝试着问问孩子：“你自己睡觉是不是感觉到黑啊？是不是想多一点时间跟爸爸妈妈待在一起呢？“\u003c/p>\u003cp>其次，用准确的语言来表达。“宝贝，其实爸爸妈妈是爱你的。我们每天都希望能多一点时间陪着你、待在一起。但是并不是说你睡在小房间就不是跟爸爸妈妈在一起了。宝贝，你看看那些小BB，他们在用奶瓶喝奶。你小时候也这样，因为那时候你还没有长出牙齿来吃食物呢。但是，当你长出牙齿来，爸爸妈妈就开始教你怎样用牙齿来吃食物、后来你就不用奶瓶了。你现在已经是大BB了，能在自己的小空间里睡觉，爸爸妈妈也是时候要教会你这一点了。”\u003c/p>\u003cp>晓勤有效使用辨认和表达技巧进行共情，引导非常好。\u003c/p>\u003cp>\u003cstrong>【小结】\u003c/strong>下面我们来简单回顾下今天拆解的主题，共情包括两个过程，第一个过程是辨认孩子的感觉，包括正面感觉和负面感觉；第二个过程是准确地用语言表达出来。 今天大家都应用了这两个是指点去催化学习应用，非常感谢大家分享，谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1498814482000,"updated_at":1498814482000,"ria":true},{"id":3077,"topic":"如何使用启发式提问技巧教育孩子？","learn_goal":"学员能用启发式提问等技巧引导孩子及一同制作惯例表还孩子自主权","remark":"关键是找到需要制作惯例表的时间段，通过启发式提问和“头脑风暴”，引导孩子想出时间段内的事情和内容；引导孩子将内容排列出顺序；可以用照片、画画、贴纸等各种方式完成制作；与孩子参与，越多越好。","level":"TF2-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"金凤","city":"东莞"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是拆书家黄金凤，我们每天都要与孩子沟通，沟通的时候，经常会有各种提问，现在有这么一种提问，除了可以跟孩子更好沟通，还可以开发孩子的思考能力，培养孩子独立思考的习惯。在接下来的拆书中会分享这种神奇的提问即启发式提问。在拆书前先分成两个组，左边一组右边一组。","ratings_count":0,"texts":[],"created_at":1498813868000,"updated_at":1498813868000},{"id":3076,"topic":"如何使用启发式提问技巧？","learn_goal":"学习及掌握启发式提问技巧，培养孩子独立思考的习惯。","remark":"用启发式提问开发孩子的思考能力，培养孩子独立思考的习惯。给孩子权力，让孩子发展自己的内心力量。","level":"TF2-1","duration":25,"status":0,"type":0,"chaishujia":{"username":"金凤","city":"东莞"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是拆书家黄金凤，我们每天都要与孩子沟通，沟通的时候，经常会有各种提问，现在有这么一种提问，除了可以跟孩子更好沟通，还可以开发孩子的思考能力，培养孩子独立思考的习惯。在接下来的拆书中会分享这种神奇的提问即启发式提问。在拆书前先分成两个组，左边一组右边一组。","ratings_count":0,"texts":[{"id":5882,"quote":"\u003cp>《行之有效的正面管教工具》作者甄颖， P118页\u003c/p>\u003cp>用启发式提问（而不是命令或者直接告诉）开发孩子的思考能力，培养孩子独立思考的习惯。\u003cbr> 关键态度：给孩子权力，让孩子发展自己的内心力量。\u003cbr> 技巧：\u003c/p>\u003cp>不要一开始问：“为什么/为什么不”，问事实，用“什么、哪里？怎样”等；\u003c/p>\u003cp>问题越具体越小，越有效；\u003c/p>\u003cp>一方很生气、烦躁时，不要提问，等双方冷静下来；\u003c/p>\u003cp>允许孩子“不知道”，引导孩子开始思考，给孩子足够时间发展独立思考的能力；\u003c/p>\u003cp>让孩子自己得出结论。\u003c/p>","explains":"\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>F:\u003c/strong>我们今天分享的书名为《行之有效的正面管教工具》，作者甄颖，“正面管教”40年前源于美国，以奥地利心理学家的“个体心理学”理论为基础，由简尼尔森和琳洛特等教育专家完善，是一个专注相互沟通的，体验式的家长教育体系。本书讲述的主要就是如何运用正面管教方法使孩子获得这种能力。\u003c/p>\u003cp>\u003cstrong>A:\u003c/strong>本书具体有以下四大优势：\u003cbr> 1、工具式编排和案例式分享大幅降低家长接受正面管教的门槛；\u003cbr> 2、12个正面管教工具好评如潮非常接地气，；\u003cbr> 3、管教故事真实有效；\u003cbr> 4、国际化视野角度点评诚恳有力，直指人心。\u003cbr> \u003cstrong>B:\u003c/strong>面对日常教育类书籍阅读中，学术类的和带案例讲解类的书，哪类你会更感兴趣？国外的案例和实践过的中国老百姓案例，哪个对你更有借鉴意义？大部分人都会选择后者，而本书恰好戳中这些痛点，满足我们家长的喜好，正面管教工具一目了然，家长们不但从书中学到易学实用的方法和工具，还可从真实的具有言传身教效果的实际案例中模仿演练，解决孩子睡觉吃饭拖拉，不听指令、轻易放弃等日常问题，帮助家长找到引导孩子自信，自律，拥有强大内心力量的成长途径。\u003c/p>\u003cp>接下来请大家阅读微信群里的原文片段，阅读完请示意。\u003c/p>\u003cp>\u003cstrong>【拆书家讲解引导】\u003c/strong>\u003c/p>\u003cp>【亲身案例】看完原文片段，这里分享一个发生在我们家的真实案例，前几个月的一天，刚下班回来看到孩子把刚买的口红涂满真皮沙发并一点不剩，不知道大家的第一反应是什么？当时我的第一反应是，恨不得抓起来一顿暴打，想着孩子还小就平复一下心情后生气地问他，你在干什么，到底在干什么……\u003c/p>\u003cp>\u003cstrong>[\u003c/strong>\u003cstrong>负面一般做法]\u003c/strong>常人反应一般是血压升高，音量升大，变成控制型家长，提一些控制型问题，例如这种提问：你在干什么，到底在干什么……你怎么能随便用妈妈的东西，妈妈不是跟你说过不能随便动妈妈的东西吗……谁让你在沙发上画画的,谁让你用妈妈的口红画画的……大家有没有发现，刚刚提过的口头禅里面有什么共同点，对，共同点是音量升高，提问问题宽泛，强调妈妈权威，\u003c/p>\u003cp>\u003cstrong>[\u003c/strong>\u003cstrong>这样做的坏处]\u003c/strong>音量升高会吓到孩子影响沟通，提问宽泛如问孩子为什么，孩子不知道具体是哪里出问题，不知道应该从哪里反思改进，老是喜欢掌握控制权例如妈妈不是跟你说过，孩子容易养成依赖习惯及缺乏自信和自主思考，这是大人对孩子提问的时候经常犯的毛病，\u003c/p>\u003cp>\u003cstrong>[\u003c/strong>\u003cstrong>拆页行动建议]\u003c/strong>而启发式提问的初衷是让孩子发展自己内心的力量，让孩子养成自己独立思考的习惯，引导孩子自己去寻找适合自己的解决方法，强调的是，将大人的控制权弱化，将选择权给到孩子。并尝试按照原文提到的平复情绪（例如深呼吸、冷静角等）——问事实（问题具体而小，用“什么、哪里？怎样”等）——引导孩子思考（允许孩子不知道，给以足够时间思考并得出结论）方法去实践。\u003c/p>\u003cp>\u003cstrong>[\u003c/strong>\u003cstrong>正面例子优化]\u003c/strong>例如我们可以冷静后这么说：你在画什么？让我猜猜，是红色的城堡么？城堡非常漂亮，现在沙发脏了，怎么办？用什么可以把沙发擦干净？画画的区域在哪里？下次如果要画画应该在哪里画？妈妈使用你的东西前会征求谁的意见，那这个口红属于妈妈的物品还是你的物品？如果要使用妈妈的物品是征求妈妈的意见还是谁的意见？\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】激活经验（显像提问）\u003c/strong>\u003c/p>\u003cp>遇到孩子喜欢唱调，胡闹不止的时候，调皮捣蛋的时候，请回想一下，下面哪个提问您曾经使用过：例如你为什么生气阿？妈妈说过这样是不对的……之前不是答应过妈妈你怎么能随便……哭能解决问题吗，妈妈是不是跟你说过遇到问题要想办法……写下这个提问，你最近一次作这个提问是什么时候，在什么场景或者背景下，结果如何？请想一想，在小组内作分享，请注意这个提问是未采用启发式提。？\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学员晓勤：孩子喜欢出去外面玩，有一次出去玩的时候碰到他的小伙伴及特别好玩的事情，就不肯走了，我跟他说：“现在要走了，马上要走了”，他说“我不回家”我说：“你干嘛不回家，现在几点了，你还不回家？”然后我不断催他走，但孩子就是不想回家\u003c/p>\u003cp>引导：感谢晓勤分享，晓勤刚刚也遇到同样的问题，就是在孩子跟我们唱反调的时候，我们父母容易变成控制型的家长，这时候就会影响跟孩子的沟通。\u003c/p>\u003cp>\u003cstrong>【A1+】（反思加工）\u003c/strong>\u003c/p>\u003cp>针对刚刚提到的场景，应用刚学到的方法，您将如何引导孩子反省并养成某习惯，现场模拟一些启发式提问。请大家模拟一下……，刚大家都经过练习相信会有更深的印象，现在请刚刚跟我们作场景分享的晓勤跟我们模拟一下她将如何使用启发式提问的。\u003c/p>\u003cp>学习者案例记录：（学员晓勤）\u003c/p>\u003cp>学员晓勤：如果让我再来一次：我会这么说：豆豆，你是想五分钟之后回家还是八分钟后回家，我们是跑步回家还是慢慢走路回家，你现在觉得哪种方式比较好呢，让他做一个选择，虽然给他选择权利，但都是围绕回家这个目标引导展开\u003c/p>\u003cp>引导：非常好，晓勤巧妙地应用了启发式提问的技巧，向孩子发出选择性式的提问，让孩子自己得出结论，这种提问对孩子来说都是非常有效的方式，除了这些，我们也还可以使用具体而小的提问等技巧。\u003c/p>\u003cp>【结语】相信大家已经对启发式提问有一定理解并且通过刚刚的练习学会怎么应用“平复情绪——问具体而小的事实——引导孩子思考”引导步骤作启发式提问，接下来希望我们少做命令型家长，多做提问型家长。感谢大家分享。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1498813702000,"updated_at":1498813702000,"ria":true},{"id":3071,"topic":"如何引导孩子制作惯例表？","learn_goal":"学员学会引导孩子制作有效的惯例表，还孩子自主权","remark":"关键是找到需要制作惯例表的时间段，通过启发式提问和“头脑风暴”，引导孩子想出时间段内的事情和内容；引导孩子将内容排列出顺序；可以用照片、画画、贴纸等各种方式完成制作；与孩子参与，越多越好。","level":"TF2-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"金凤","city":"东莞"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":null,"ratings_count":0,"texts":[],"created_at":1498802867000,"updated_at":1498802867000},{"id":2895,"topic":"正面管教工具","learn_goal":"当孩子犯错的时候，我们如何做到自我调整情绪并帮助孩子解决问题","remark":"“正面管教”体系近40年前源于美国，以奥地利心理学家Alfred Adler和Rudolf Dreikurs的“个体心理学”理论为基础，由简尼尔森和琳洛特等教育专家完善，是一个专注相互沟通的，体验式的家长教育体系。\r\n\r\n本书按照家长学习偏好，以11个深受中国家长欢迎的代表性工具入手，用家长真实案例来介绍正面管教方法和理念。工具式编排和案例式分享大幅降低家长接受正面管教的门槛。让正面管教可以帮助到更多家长。","level":"TF2-4","duration":60,"status":0,"type":0,"chaishujia":{"username":"李欢","city":"上饶"},"club":{"name":"上饶三清山分舵","city":"上饶"},"prologue":"开场：大家好，我是李欢。今天我要拆的书是《行之有效的正面管教工具》。","ratings_count":0,"texts":[{"id":5676,"quote":"\u003cp>\u003cstrong>一、学习目标：\u003c/strong>\u003c/p>\u003cp>在跟随我完成第一次本次RIA现场学习后，学习者能够认识到：\u003cstrong>对他人发脾气后的利用四个步骤平复情绪并找到自己的责任与错误”。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>二、图书介绍\u003c/strong>（1-2分钟）\u003c/p>\u003cp>\u003cstrong>F \u003c/strong>\u003cstrong>特征\u003c/strong>\u003cstrong>（核心是“书”，用于满足好奇心）：\u003c/strong>\u003c/p>\u003cp>这本书的作者是甄颖，美国认证“正面管教讲师”，国内点击量最高育儿博客“混血小美”博主，前欧洲媒体记者。\u003c/p>\u003cp>是一本育儿类的工具书籍。是全国各地正面管教学习者成果使用工具解决问题的例子，作者对于其进行点评，总结高度概括的这一本书。\u003c/p>\u003cp>\u003cstrong>A \u003c/strong>\u003cstrong>优势（重点是“比较”，用于建立安全感）：\u003c/strong>\u003c/p>\u003cp>这书的原则和理论基础是正面管教，国内目前发展的最好最强大的一套育儿体系。《行之有效的正面管教工具》13年上市，就在三大网站出现疯抢，连续断货状态。它其他学术类书籍相比较，本书的特点是：大篇幅大篇幅的成功使用正面管教工具的例子，例子是非常贴近生活的吃饭刷牙睡觉等等等这一系列我们日常中碰到的问题。\u003c/p>\u003cp>\u003cstrong>B \u003c/strong>\u003cstrong>利益\u003c/strong>\u003cstrong>（强调的是“学习者”的利益，用于引发兴趣）\u003c/strong>\u003c/p>\u003cp>&nbsp;大家会不会有这样的感觉，看了那么多书，上了那么多课，结果碰到问题还是不知道该怎么办？孩子不吃饭，打闹，不合作，不睡觉等等这些事情我们改怎么办呢？这本书里的成果的例子可以帮助大家如何正确使用正面管教育儿工具。\u003c/p>\u003cp>\u003cstrong>第一个拆页\u003c/strong>\u003c/p>\u003cp>\u003cstrong>三、【R】阅读原书拆页\u003c/strong>（约1分钟）\u003c/p>\u003cp>我们永远不会遇到一个大脑盖子永远合起来的人，没有人能始终保持理智、冷静、耐心。只要是人，就会发脾气的时候，而妈妈这个职业，更是常常面对自己发脾气的时刻。我们都是这样。我们都希望自己能够不对孩子发脾气，或者尽量少发脾气。\u003c/p>\u003cp>自责和内疚是必经过程，但是不能解决问题。\u003c/p>\u003cp>意识是成功的开始，家长要意识到自己问题中的责任，需要承担的部分是什么？通常只要发发生问题，所有参与的人，都有或多或少的责任。家长要问自己：有没有强迫孩子？有没有说教孩子？有没有对孩子啰嗦？\u003c/p>","explains":"\u003cp>\u003cstrong>四、【I】拆书家讲解引导\u003c/strong>（约4分钟)\u003c/p>\u003cp>这个片段主要是讲了，发脾气是很正常的，但是事后这些内疚、自责、担心、焦虑等等这些负面情绪都不能解决问题，我们要意识到自己在这件事情中的责任，和错误是什么？那我们要做的是什么？原文中已经给了我们指引：不光我们发脾气造成了伤害，是不是事情本身也或多或少也有责任和错误，我们要很清晰的明确的找到自己在问题中的责任和错误。\u003c/p>\u003cp>(贴切的例子)\u003c/p>\u003cp>想举个我自己的例子：我儿子还小的时候，早上起很晚了，还拖拉去上学迟到，我很生气，答应早上去买雪糕给他吃，我就是不给他买，还把他从家里拿到雪糕扔在地上。儿子当时就委屈的哭了，我还要求他不准哭！哭什么哭？拖拖拉拉！就是不准吃！拿一个仍了一个！\u003c/p>\u003cp>上班之后，我就很纠结、很担忧、很自责：孩子上学总迟到，以后上小学了，大了上班了怎么办呢？自己刚才这对孩子，造成伤害了！怎么办呢？一早上我就纠结，痛苦，难过，焦虑，自责！差点就流眼泪了。一早上状态都非常不好！当我意识到了负面情绪无用于孩子和自己，同时对于事情本身的错误和责任我还没有找到！我是不是必须找到自己的责任和错误？\u003c/p>\u003cp>我就做了下面几步：（细化步骤）\u003c/p>\u003cp>1、深呼吸，或停顿几分钟。平复一下自己的情绪。\u003c/p>\u003cp>2、自我对话：这世上有永远都理智冷静，大脑盖子永远合上的人吗？（我就想到了正面管教的创始人简尼尔森说她去上课之前：还拿鞭子打了她女儿这件事情，瞬间释怀了）\u003c/p>\u003cp>3、我现在这些复杂的情绪能帮助到孩子和自己吗？（当然不能）\u003c/p>\u003cp>4、认真分析一下自己在这件事情上我应该承担的责任和错误？（早上拖拉我的责任在于：没有早一点叫儿子起床，用了吼叫和谩骂的方式让儿子配合，我没有控制好自己的行为，说话不算数没有买冰激凌给孩子，不尊重孩子）\u003c/p>\u003cp>（不这样做的坏处）：大家想想，我们陷入自责内疚情绪后，就会非常非常焦虑，越焦虑状态越糟糕，孩子是不是会体察到我们的焦虑，这样做其实对孩子一点帮助也没有，问题没有得到解决。很容易就出现恶性循环状态！\u003c/p>\u003cp>同样的，我只是察觉到了我打骂孩子的责任和错误是不是也不一定能解决问题，早上迟到这件事情本身我也是有责任和错误的是吗？这样才能真正担起我的责任，才有可能和孩子心连心，并教会孩子承担起自己的责任和错误。\u003c/p>","interaction":"\u003cp>\u003cstrong>四、【A1】\u003c/strong>（约6分钟）\u003c/p>\u003cp>请伙伴们想想：在过去的一周或两周内，有没有孩子或者我们的爱人，父母，朋友做了一件事物，你非常生气愤怒沮丧失落或者别的情绪，你当下就发脾气了！表现的很情绪话！事后呢，又陷入担心又焦虑又害怕自责内疚等负面情绪，脑中一直在想：我真不该发脾气的，我不该这样对他的，我做错了，唉 ！我孩子以后怎么办啊？会怎么样怎么样……我爱人会怎么样怎么样，我真不是个好妈妈，好老婆，好同事，好人……有没有这样的情况，当时的情形是怎么样的！过程如何？\u003c/p>\u003cp>纪老师分享：刚才来的时候我就对我女儿发火了，现在挺后悔的。因为养狗的事情，她抱着狗一只舔啊，抓啊，摸啊，然后狗狗的东西到处乱七八糟的，她没有实现她的承诺，东西没整理，我很生气，让她赶紧的把狗放回去，东西整理好！当下是发了很大的脾气，很生气。其实这件事情一直就在这里。\u003c/p>\u003cp>拆书家回应：也就是说问题始终都没有得到很好的解决是吗？恩，好的，谢谢纪老师的分享！\u003c/p>\u003cp>那纪老师是否能现场用这四个步骤平复一下自己的情绪并找到自己的错误和责任吗？\u003c/p>\u003cp>纪老师：恩，好的。\u003c/p>\u003cp>首先：\u003c/p>\u003cp>1、深呼吸，或停顿几分钟。平复一下自己的情绪。\u003c/p>\u003cp>2、自我对话：简尼尔森说她去上课之前：还拿鞭子打了她女儿这件事情，瞬间释怀了。好像我还没有到哪一步啊，还不算太坏的妈妈。\u003c/p>\u003cp>3、我现在这些复杂的情绪能帮助到孩子和自己吗？（当然不能）\u003c/p>\u003cp>4、认真分析一下自己在这件事情上我应该承担的责任和错误？我这过程是使用了比较暴力的解决方式，我本来应该控制好自己的情绪，用引导的方式去解决的。我还翻了旧账，没有就事论事。还有在之前呢，我就已经预见到了会有这样的问题，我没有做好防御措施，而且也没有提前提醒孩子。这些是我要负起责任的地方，和错误所在。\u003c/p>\u003cp>拆书家：好的！非常感谢纪老师！\u003c/p>\u003cp>还有小伙伴愿意分享吗？\u003c/p>\u003cp>没有我们就继续好吗\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":5677,"quote":"\u003cp>好！那我们找到错误和责任在哪里了，接下来那我们怎么对方和好呢？怎么去解决这个问题呢？\u003c/p>\u003cp>正面管教里有一个从错误中恢复的4个R步骤简单有效\u003c/p>\u003cp>\u003cstrong>第二个拆页\u003c/strong>\u003c/p>\u003cp>\u003cstrong>五、学习目标：\u003c/strong>\u003c/p>\u003cp>利用4R合孩子重新和好建立连接并想出解决办法！\u003c/p>\u003cp>\u003cstrong>六、【R】阅读原书拆页\u003c/strong>（约1分钟）\u003c/p>\u003cp>1、承认。\u003c/p>\u003cp>2、链接。\u003c/p>\u003cp>3、和好。\u003c/p>\u003cp>4、解决问题。\u003c/p>","explains":"\u003cp>\u003cstrong>七、【I】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>（异议）\u003c/p>\u003cp>大家会不会想：万一孩子不愿意接受我的道歉怎么办？\u003c/p>\u003cp>我开始也非常的担心这点，但是经过我无数次的试验，请大家放心：孩子比我们想象中的要宽容的多，甚至要爱我们多一点。自己的丈夫，父母其实也是一样的，一句真心的“对不起”真的可以换来很多很多的拥抱和爱，这一点请大家放心。我相信即使是你的朋友，只要听到你真心的真诚的话语，都会愿意和解的！\u003c/p>\u003cp>（适用边界）当然了这个办法，是我们生命里比较在乎的人，如果是路人甲乙丙，我们当然不需要去运用这些东西！\u003c/p>\u003cp>（预防异议）当然了，我们对他人造成了伤害，我们可以用这样的工具还平复，修补这个错误和伤害，但是这不是我们下一次发脾气的原因和后盾啊！我们最终还是要做到控制好自己的情绪尽量少发脾气！不得已的情况才使用这个工具。这个道歉一定是真诚的，发自内心的，而不是用来为自己解脱的一个理由。\u003c/p>\u003cp>我举个我刚才的例子：\u003c/p>\u003cp>当我晚上一回家，我就看到儿子在玩，他似乎忘记了我和他早上的事情了，孩子是多么的宽容。但是我想伤害还在，我必须要用爱去弥补。\u003c/p>\u003cp>一：承认：我抱着儿子到房间里：“宝贝，妈妈早上犯了好几个错误，伤害到你了，妈妈跟你说对不起。”儿子一愣，好像回想起来了，有点眼含泪水了。“早上你迟到了，妈妈有几点错误：1、说好早一点叫你，没有准时叫你。2、妈妈很着急担心被老师骂，用了很暴力的语气命令你快点，伤害到你了。3、妈妈答应给你买冰激凌没有给你买。4、妈妈把你的冰激凌仍了，很不尊重你。”\u003c/p>\u003cp>我儿子当时眼泪就掉下来了。\u003c/p>\u003cp>二：链接\u003c/p>\u003cp>共情做链接：“这个过程，你一定觉得很委屈，很伤心，很受伤，很难过，是吗？你也希望早上早一点起床，吃着冰激凌和妈妈开开心心的一起上学是这样吗？”\u003c/p>\u003cp>三：和好\u003c/p>\u003cp>我儿子一直在点头：说是的。\u003c/p>\u003cp>我说：“妈妈跟你说对不起，妈妈已经知道自己错了，你愿意原谅妈妈吗？”于是我和儿子两个人抱在一起。算是和解了。\u003c/p>\u003cp>四：解决问题\u003c/p>\u003cp>我接着说：“谢谢宝贝，妈妈爱你。那我们明天怎么样早一点起床，不迟到呢？“\u003c/p>\u003cp>于是我们就开始头脑风暴，解决问题了。我们定了闹钟，早上早早起床，一起刷牙洗脸吃饭。\u003c/p>\u003cp>第二天我买了大盒的冰激凌边走边吃。\u003c/p>","interaction":"\u003cp>\u003cstrong>七、【A3】促动参与\u003c/strong>\u003c/p>\u003cp>好的，下面我们来运用一下这个五步骤。\u003c/p>\u003cp>小李带着孩子一一出去玩，回来路上呢！一一把自己的水杯这个月第五次给弄掉了，这回是掉在出租车上！那妈妈第一反应是很生气哦！就骂一一了，：“怎么回事？一天到晚丢三落四，再也不给你买杯子了，以后都不要喝水，自己到幼儿园去拿纸杯喝水！自己想办法！”\u003c/p>\u003cp>一一很生气，就说：“不喝就不喝，我才不想要你买的杯子”\u003c/p>\u003cp>两人都很生气。几分钟后，妈妈情绪平和了又很自责哦，觉得自己最近总发脾气，总控制不住自己脾气，觉得自己不是个好妈妈。刚好呢昨天晚上学习了这两个工具啊，那请妈妈运用这个从错误中回复的4R和孩子和解，并找到解决问题的办法。小组讨论，扮演一下角色。\u003c/p>\u003cp>可能开始的时候大家不太熟悉，我们就用这个基本套路来试试，供大家参考，请大家翻到下一页：可以用这个细化的步骤：\u003c/p>\u003cp>一：承认：\u003c/p>\u003cp>“宝贝，妈妈犯了个错误，伤害到你了，妈妈跟你说对不起。\u003c/p>\u003cp>1、\u003c/p>\u003cp>————————————————————————————\u003c/p>\u003cp>2、\u003c/p>\u003cp>————————————————————————————”\u003c/p>\u003cp>二：链接\u003c/p>\u003cp>“这件事情，你一定很希望是这样的：\u003c/p>\u003cp>————————————————————————————，\u003c/p>\u003cp>妈妈这样对你，你一定感觉很\u003c/p>\u003cp>————————————————————————————，\u003c/p>\u003cp>是这样吗？你愿意给妈妈一个拥抱吗？或者妈妈想抱抱你可以吗？”\u003c/p>\u003cp>三：和好\u003c/p>\u003cp>恩，我说：“对不起妈妈错了，妈妈是担心——————————，妈妈希望——————————————————————。”\u003c/p>\u003cp>四：解决问题\u003c/p>\u003cp>启发式提问：那我们怎么样才可以把这个问题解决掉呢？我们一起来想一想好吗？\u003c/p>\u003cp>请小组分享一下好吗？\u003c/p>\u003cp>兰老师和王老师分享：\u003c/p>\u003cp>兰：一宝，刚才妈妈那么大声对你吼叫，肯定吓到你了吧。对不起。\u003c/p>\u003cp>这件事情，你其实也是很希望可以保管好你的东西，也希望可以把自己的带回来是吗？\u003c/p>\u003cp>王：是的，妈妈。\u003c/p>\u003cp>兰：你愿意给妈妈一个拥抱吗？\u003c/p>\u003cp>恩，抱抱\u003c/p>\u003cp>兰：其实妈妈是希望可以养成一个保管好东西的习惯，妈妈担心你把自己心爱的东西弄没了。\u003c/p>\u003cp>拿我们一起想个办法，怎么样才能解决掉这个问题呢？我们一起想一想好吗？\u003c/p>\u003cp>王：恩，我们可以买个可以挂在身上的水杯，这样出门就不会掉了。\u003c/p>\u003cp>兰：唉！不错，这主意挺好的！那我们是现在去买还是怎么？\u003c/p>\u003cp>王：我要米奇的，现在就去买！\u003c/p>\u003cp>兰：好嘞，走吧。\u003c/p>\u003cp>拆书家：非常感谢两位精彩的演出！谢谢，大家掌声鼓励！扮演的过程有什么感觉吗？\u003c/p>\u003cp>王璐老师：我感觉其实我也不想丢杯子的，但是妈妈的整个过程，我感觉很舒服，很开心，被理解到了，而且问题的解决办法是我自己想出来的。这点很好！我回去马上就使用。\u003c/p>\u003cp>兰老师：恩，是蛮实用的，我也准备回去试试。\u003c/p>\u003cp>这边两位小伙伴是不是也分享一下呢：\u003c/p>\u003cp>李：一一，刚才妈妈那么大声对你，对不起，其实妈妈也没有提醒到你，妈妈也有一定的责任。\u003c/p>\u003cp>纪：恩，是的，我很难过，我也不想弄丢我的水杯\u003c/p>\u003cp>李：你一定觉得很害怕，很失望，很难过伤心吧！恩恩，你一定也很想开开心心的出去，高兴的回来，也想保管好自己的水杯的。\u003c/p>\u003cp>纪：是的。\u003c/p>\u003cp>李老师：对不起啊，宝贝，你愿意给妈妈一个拥抱吗？好吧！抱抱\u003c/p>\u003cp>李老师：妈妈希望我们下次出去可以把东西都带回来，那我们想一想我们怎么样才能下次不弄丢水杯呢？\u003c/p>\u003cp>纪老师：恩，那我买自己喜欢的水杯，这样我会一直拿着。\u003c/p>\u003cp>李老师：恩，那妈妈给你出个主意，可以在水杯上写你的名字，你觉得这样好吗？\u003c/p>\u003cp>纪老师：恩，好主意，拿我们去买吧\u003c/p>\u003cp>李老师：好啊！我们去买吧。\u003c/p>\u003cp>拆书家：哇！非常精彩的演出！\u003c/p>\u003cp>大家自发鼓掌\u003c/p>\u003cp>恩！\u003c/p>\u003cp>\u003cstrong>八、【A2】催化运用\u003c/strong>\u003c/p>\u003cp>好的，那我们也帮助到别人了，我们是不是要在实际生活中运用起来呢？这个下一周来了，新的一周开始了，在家里可能孩子，丈夫，父母会不会做什么事情，让你脾气大发，在单位会不会和很好的同事有什么事情，让你脾气大发，和好朋友聚会啊，等等这些情景，你如何运用这四个步骤去和你身边的人和解，并找到解决办法。请小组内讨论一下。\u003c/p>\u003cp>有没有小伙伴愿意分享的！有有结果的吗？分享一下好吗？\u003c/p>\u003cp>李老师：我来分享一下！\u003c/p>\u003cp>每周一我都会对我学生发一顿火，总有学生单词不背，作业不写，课文不背！每次都是要发火！好像都解决不了问题！这个问题一直都在\u003c/p>\u003cp>那如果明天我又对学生发脾气了，下课的时候，我就叫学生来我办公室。这样学生说：\u003c/p>\u003cp>某某，刚才老师对你发脾气了，你肯定挺难过，挺尴尬，挺伤心的吧！你是不是也希望可以背好课文，写好单词。可能是时间的原因，或者其他的什么原因？恩，老师也没有提前做好布置，可以早一点告诉你家长，在一点提醒你们。\u003c/p>\u003cp>老师跟你道个歉。\u003c/p>\u003cp>这样，我们一起来想个办法。怎么样才能让你在周末的时候把作业正常做完，功课备完，单词写完呢？\u003c/p>\u003cp>看看这样是不是可以缓解和学生的关系，甚至解决问题！\u003c/p>\u003cp>拆书家：非常感谢李老师精彩的分享！\u003c/p>\u003cp>当然了再一次提醒，我们对他人造成了伤害，我们可以用这样的工具还平复，修补这个错误和伤害，但是这不是我们下一次发脾气的原因和后盾啊！我们最终还是要做到控制好自己的情绪尽量少发脾气！不得已的情况才使用这个工具。这个道歉一定是真诚的，发自内心的，而不是用来为自己解脱的一个理由。\u003c/p>\u003cp>非常感谢分享！分享中我们看到。\u003c/p>\u003cp>\u003cstrong>九、结语\u003c/strong>\u003c/p>\u003cp>今天我们的学习部分就到这里。通过两个片段的学习，怎么多激烈的讨论，我相信当我们陷入内疚自责之后，我们依然有能力去弥补这个遗憾，用爱的力量去疗愈双方的痛苦，加强心与心的链接。今天我的拆书就到这里，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1497232864000,"updated_at":1497232864000,"ria":true},{"id":2701,"topic":"在尊重自己和孩子的同时建立良好的沟通模式找到最有效的解决问题","learn_goal":"尊重自己和孩子的同时建立良好的沟通模式，找到最有效的解决问题","remark":"生活中当我们和孩子相处时会遇到许许多多的挑战，孩子做事拖拉，不按时睡觉，容易发脾气，喜欢玩手机或电脑游戏……虽然每个孩子给予的挑战不一样，但有意思的是这些挑战确实或多或少都存在于每个家庭。当面对这些形形色色的挑战时有些家长脸上写着大大的无奈，在要求孩子无果时只能做出让步，选择短暂性的逃避，本着眼不见为净的原则做出妥协。","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"饶晶晶","city":"上饶"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"开场： 大家好，我是饶晶晶，乐观、开朗、充满正能量的新手拆书家。今天我训练的是《拆书家手册》V3的TF1-2，用How片段和大家一起学习，将便签法的R、I、A三个环节理解的更加透彻。接下来为我们今天的拆书活动做准备，我们需要分一下小组。（现场根据人数灵活分配） 我今天带拆的图书是《行之有效的正面管教工具》，本书作者是甄颖，她是美国正面管教资质导师，也是育儿博主，育儿博客国内访问量最高达到3700万。《行之有效的正面管教工具》中通过实践在正面管教之路上宝妈们的真实育儿故事分享引导出正面管教中的十二个有效工具。有了这些工具家长们就如同有了法宝，可以轻而易举的拿下育儿途中的遭遇的各种“小怪兽”。在尊重自己和孩子的同时建立良好的沟通模式，找到最有效的解决问题的方法。","ratings_count":0,"texts":[{"id":5447,"quote":"\u003cp>共同解决问题的7个步骤\u003c/p>\u003cp>&nbsp; &nbsp;1.开始谈话。\u003c/p>\u003cp>&nbsp; &nbsp; 找个双方都情绪都平稳的时间和地点，和孩子坐下来：“我有件事想跟你谈谈，就是_______。我希望咱们能一起找到解决方法，你愿不愿意谈一谈？妈妈保证不发脾气，不生气。咱们都保证不互相指责？”——最后一句最重要，目的是为了保证谈话的情绪安全。\u003c/p>\u003cp>&nbsp; &nbsp;2.倾听孩子的想法。\u003c/p>\u003cp>&nbsp; &nbsp; 如果孩子不同意，告诉Ta：“好，我明白。等你想听的时候咱们再谈。”——不强迫，情绪安全。如果孩子同意，问；“你对这件事有什么想法？”你的感觉是什么？”听孩子说完后，用共情重复孩子的话。——让孩子先说，家长先听。倾听的同时，只需要共情即可，而不要点评，也不要着急给孩子讲道理。如果孩子说不出自己的感觉，家长可询问：“是不是觉得……”\u003c/p>\u003cp>3.说出自己的感受。\u003c/p>\u003cp>&nbsp; &nbsp; 听完孩子说完，问孩子：“你想不想听听妈妈的感觉是什么？”妈妈的感觉可能和你的不一样，这很正常，每个人的感觉都不一样。”然后，诚实的告诉孩子你的感觉。使用“我”句式。——告诉孩子“每个人感觉不一样，这很正常”，和第一步的最后一句同样重要。这一步不容易的地方，在于诚实地告诉孩子你的感觉，而不是你的道理。有家长到了这里就不由自主地将谈感觉变成了讲道理。谈感觉是谈心，讲道理则容易变成说教。\u003c/p>\u003cp>&nbsp; &nbsp; 4.感谢孩子。\u003c/p>\u003cp>&nbsp; &nbsp; 说完以后感谢孩子：“谢谢你听我说，也谢谢你告诉我你的感觉。”——这样的感谢虽然简单，但对于培养孩子和家长谈心的习惯，也就是前面3个步骤，非常有帮助。\u003c/p>\u003cp>&nbsp; &nbsp; 5.启发孩子解决问题的方法。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;问孩子：“你觉得你/我们能做些什么，来解决这个问题/困难？”或者使用启发式提问，听孩子说，或和孩子一起头脑风暴”。不批评、点评、否定孩子提出建议。可点头、微笑、“嗯”等表示听到了。——即使孩子的建议不可行，也写下来，以示对孩子的尊重。家长也可参与“头脑风暴”，目的是为了培养孩子独立思考的能力。如果孩子没有建议，家长也可自己提出建议。这时候，直接告诉孩子应该怎么做的“正面语言”，给孩子有限权力的“选择”，都可以使用。这时候，也可以适当给孩子讲道理，让孩子思路清晰理智。\u003c/p>\u003cp>&nbsp; &nbsp;6.选定解决方案。\u003c/p>\u003cp>&nbsp; &nbsp; 对于最可行和尊重双方的方式，最好由孩子自己选择。——孩子是当事人，自主选择为后面的执行打下良好的基础。\u003c/p>\u003cp>&nbsp; &nbsp; 7.约定回顾时间。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;约定一个时间来回顾、表达感激。——行大于言。前6步都是说，最后还是要落实在行为上。约定的时间不用太长，baby step，让孩子容易看到小进步，巩固执行效果，或者及时调整不当行为。\u003c/p>","explains":"\u003cp>生活中当我们和孩子相处时会遇到许许多多的挑战，孩子做事拖拉，不按时睡觉，容易发脾气，喜欢玩手机或电脑游戏……虽然每个孩子给予的挑战不一样，但有意思的是这些挑战确实或多或少都存在于每个家庭。当面对这些形形色色的挑战时有些家长脸上写着大大的无奈，在要求孩子无果时只能做出让步，选择短暂性的逃避，本着眼不见为净的原则做出妥协。而有些家长则会火冒三丈，责骂呵斥Ta立即、马上将错误改正否则后果很严重。显而易见这两种方式对于解决问题都没有长期的效果可言。前者直接忽视孩子，后者将孩子处在一个感觉很糟糕的境地，它们都忽略了解决问题前需要先和孩子进行情感的连接。想要长期有效的解决问题需要做到以下几点：首先我们要制造一个情绪安全的氛围让孩子敢说，用心倾听孩子的感受，放下自己的指责埋怨，只是做一个忠实的听众。再诚实的说出自己的感觉，放弃长篇大论的说教，只是让孩子明白每个人都可以有自己的感受，感受可以不一样，感受没有对错之分。倾听和说出自己的感受可以让自己和孩子处于同频状态，让之后的良好沟通变得水到渠成。接下来真诚的感谢孩子的交谈，适当的时候给予拥抱和鼓励，这些小技巧是滋养亲子关系的必要养分。然后用启发式提问的方式培养孩子独立思考解决问题的能力，放开手让孩子自己思考，只是在旁边做一个引导者。最后选择一个经过Ta自己思考的可执行的方案落实并约定回顾时间巩固执行效果。整个过程都要以尊重孩子和尊重自己为前提，解决问题之前先连接情感。养育孩子的道路很漫长，但我们不能走得太着急，因为太着急我们就会忽略很多沿途的美景。放慢脚步，用心倾听孩子，现在的“慢”是为了以后轻松地走的得更远。\u003c/p>","interaction":"\u003cp>\u003cstrong>激活经验\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>现在请大家回想一下你们在平常和孩子或Ta人的相处过程中有没有急于想解决问题而忽略对方情感的例子？每组有五分钟组内互相分享时间，结束后邀请代表向大家分享一下自己的案例。\u003cbr>\u003c/p>\u003cp>学习者案列记录：\u003cbr>\u003c/p>\u003cp>&nbsp;四年级孩子小B总是不能按时完成作业，每天都拖拖拉拉，昨天晚上他又做到很晚，妈妈很愤怒“天天要做到这么晚，你动作就不能快一点吗？”孩子瞪了妈妈一眼“不用你管，你出去”。\u003c/p>\u003cp>\u003cstrong>\u003cstrong>【A2】\u003c/strong>催化应用\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>今天我们共同学习了解决问题的7个步骤，相信大家对每个步骤该说的话该做的动作都有了清晰的概念。现在请大家用一分钟的时间写下你将这7个步骤怎样应用到未来的生活中，注意我们写下的内容不是空想和决心，而是在明确的时间、地点、人物都有的场景中我们具体的做法。\u003cbr>\u003cstrong>学习者案例\u003c/strong>\u003cstrong>记录：\u003c/strong>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>时间：晚饭后的散步时间\u003c/strong>\u003c/p>\u003cp>\u003cstrong>地点：家里\u003c/strong>\u003c/p>\u003cp>\u003cstrong>人物：刘妈妈和孩子宝儿\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1\u003cstrong>.\u003c/strong>宝贝，妈妈有件事想跟你谈谈，就是关于你玩电脑游戏的事。在谈话过程中妈妈保证不生气，你愿意和我谈谈吗？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2.对于你每天玩几个小时的电脑游戏，你的感受是怎么样的，能告诉我吗？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3.妈妈的感受是很担心，担心你的视力会下降。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>4.谢谢你可以心平气和的和妈妈聊这些。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>5.我们是不是可以一起共同想一些解决的方法呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>6.那我们就暂时选定A方案。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>7.一个星期以后看它是否有效果，再决定是否继续使用。\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1495592814000,"updated_at":1495592814000,"ria":true},{"id":2700,"topic":"在拆书帮人人都是参与者，大家都在一个平等和谐的环境中成长","learn_goal":"大家都在一个平等和谐的环境中不断完成自我成长和突破。","remark":"人有时候会害怕，是因为不知道接下来会发生什么事情。未知事件是多数人感到恐惧的原因。特别是小孩子，当你把Ta突然放到一个陌生的环境面对陌生的人群，Ta会很没用安全感。","level":"TF1-1","duration":10,"status":0,"type":0,"chaishujia":{"username":"饶晶晶","city":"上饶"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是饶晶晶，下面我想用三个标签简单的介绍一下自己。1.我是四周岁女孩徐怡霏的妈妈，有人说女子本弱、为母则刚，感谢女儿让我变得更加有力量，有了她以后我想要成为更好的那个自己。2.教师，我在广丰区特殊教育学校教聋哑的孩子，感谢这群折翼的天使让我更懂得了爱和感恩3.自由创业者，除了教书我自己还开了一家琴行和一家幼儿园，感谢学生和家长们对我的信任，让我可以一直带着这一份力量前行，希望不久的将来我还能加上一个标签,那就是成为拆书帮的三级拆书家。感谢大家今天能在百忙之中抽空参加这个活动，陪伴我一同朝目标迈进一步。\r\n二、拆书帮介绍（2分钟）\r\n “拆书”是一种学习方法，“拆”不是“拆散”而是转化和内化。强调把图书的知识拆页转化为学习者的能力。成人可以通过拆书提升能力，解决问题。强调以学习者为中心，而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。 \r\n 拆书法分为应用于个人学习的拆书帮便签法和应用于组织学习的拆书帮现场学习法。其中个人便签发包括R、I、A三个环节，R是指阅读原文拆页，I环节是拆书家对原文知识拆页的","ratings_count":0,"texts":[{"id":5446,"quote":"\u003cp>&nbsp; “提前说”，看似很小，可起到的作用非常大。用具体而清晰的语言，提前告诉孩子接下来要做什么，会给孩子带来很大的安全感！\u003c/p>\u003cp>&nbsp; &nbsp;否则，孩子的事情都有大人安排，虽然大人心里很清楚接下来要做什么，但不告诉孩子，那么孩子的心中依然一片茫然，惶惑。再加上被动地遵从，是最容易发生矛盾的时刻之一。\u003c/p>\u003cp>&nbsp; &nbsp;“提前说”几乎可以用于一切场合。另一位从“正面管教妈妈”成长起来的“正面管教讲师”梁良，曾很惊喜地分享过她对1岁2个月儿子“提前说”的效果：以前一到要下楼的时间，我儿子就急，稍微慢一点他就哭，就闹。后来，快到时间的时候，我提前告诉他：“等一下妈妈要先去洗手间，然后把你的东西准备好，然后给你穿外套，穿鞋，然后妈妈穿鞋。然后我们就一起下楼玩了。”虽然我儿子才一岁，可是竟然都明白，耐心地等我做完这些事，不再哭闹了！\u003c/p>\u003cp>&nbsp; &nbsp;“提前说”就是给孩子机会，让孩子对未来做好准备。所以，提前说的语言越详细越具体越好。\u003c/p>","explains":"\u003cp>假如在你们面前有一个不透明的袋子，让你用手摸一摸里面的东西，你会有什么感受呢？害怕，紧张？但如果我告诉你袋子里面装的是一个毛绒玩具，你是不是就不那么恐惧了。人有时候会害怕，是因为不知道接下来会发生什么事情。未知事件通常多数人感到恐惧的原因。特别是小孩子，当你把Ta突然放到一个陌生的环境面对陌生的人群，Ta会很没有安全感。不知道接下来该做什么，更没有信心相信自己能够做好。孩子缺乏安全感时通常的表现是哭闹或想要逃离。如果家长提前用清晰的语言详细具体的告诉Ta接下来会遇见什么事情和该做些什么可以避免感到不知所措而引发一系列的负面情绪。“提前说”可以将问题终止在萌芽期，让亲子沟通变得更顺畅。\u003cbr>\u003c/p>","interaction":"\u003cp>A1\u003c/p>\u003cp>女儿三周岁时每次午睡或早晨睡醒后看身旁没人就大哭不止。有时我正专心做一件事情一听到她撕心裂肺的哭声就得急忙跑进房间。接下来是一阵安慰。这样的场景每天都上演却又无力改变。看着眼前这个哭的很伤心的小家伙心里的感觉是烦躁而又无奈。后来我尝试用“提前说”，睡觉前我告诉她：“宝贝，妈妈可能会醒的比你早一些，如果你醒来后没看见妈妈就大声叫一下我好吗？那样我就可以马上“飞”到你身边。或者你也可以自己穿上鞋子出来找妈妈，然后偷偷站在妈妈身后吓我一大跳”。女儿听完后爽快的答应了。第二天早晨我正在厨房准备早餐，她醒来后没有哭闹而是自己下床穿上鞋子走到我身后吓我一跳。我抱了抱她，愉快的一天从就这样开始了。更神奇的是从那天以后起床看不见人哭闹的现象再也没有发生过。可见“提前说”可以给予孩子强大的安全感。\u003c/p>\u003cp>A2\u003c/p>\u003cp>（1）将“提前说”应用到日常惯例表的活动实施中\u003cbr>\u003c/p>\u003cp>例如：“小宝，再过五分钟动画片时间就结束了，我们接下来需要做的是洗漱然后上床睡觉”。提前说可以让孩子有心理准备，不会对接下来要做的事情报以抵触的心理。\u003c/p>\u003cp>（2）需要带女儿外出吃饭或者参加活动时提前告知，给予她有限的选择。\u003c/p>\u003cp>例如：霏，今天妈妈办公室的一个阿姨请吃饭。有一些人你是没有见过的，可能会觉得有些陌生。而且我们的用餐时间可能会有些长，你现在自己决定是不是要和妈妈一起去，好吗？\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1495592443000,"updated_at":1497162042000,"ria":true},{"id":2679,"topic":"如何利用“共情”技巧引导孩子？","learn_goal":"学员能利用“共情过程”的两个步骤引导孩子，达到教育孩子的目的","remark":"很多家长对如何教育孩子感到迷茫？本期拆书将介绍“共情”的管教工具。共情的过程首先自己要理解孩子，其次接纳孩子，再次是认可孩子，然后才能引导孩子准确表达或引导孩子说出自己的希望。具体如何做？请参与本期的拆书活动，不见不散！","level":"TF1-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"金凤","city":"东莞"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好我是今天拆书家黄金凤，很高兴大家来到我们拆书现场。我们在拆书前先成两个小组，前面的几位小伙伴一个小组，后边的小伙伴为一个小组，一会儿我们会按照分组进行讨论。","ratings_count":0,"texts":[{"id":5421,"quote":"\u003cp>&nbsp;（R）&nbsp;“共情”是心理学术语，又叫同感、同理心。共情的过程是：一、辨认孩子的感觉，包括正面感觉和负面感觉；二准确地用语言表达出来。&nbsp;\u003c/p>","explains":"\u003cp>我们今天分享的书名为《行之有效的正面管教工具》，“正面管教”各位伙伴相信近40年前源于美国，以奥地利心理学家的“个体心理学”理论为基础，由简尼尔森和琳洛特等教育专家完善，是一个专注相互沟通的，体验式的家长教育体系。本书按照家长学习偏好，以11个深受中国家长欢迎的代表性工具入手，用家长真实案例来介绍正面管教方法和理念。工具式编排和案例式分享大幅降低家长接受正面管教的门槛。让正面管教可以帮助到更多家长。作者甄颖，美国认证“正面管教讲师”，简尼尔森亲导中国讲师，其微博上的自我介绍是“做想给、会给孩子自由、尊重、权力的妈妈”。&nbsp;\u003c/p>\u003cp>本次拆解为该书籍第16页其中一个片段，请大家看微信……看完的小伙伴请示意。\u003c/p>\u003cp>本片段主要强调共情的过程首先自己要理解孩子，其次接纳孩子，再次是认可孩子，然后才能引导孩子准确表达或引导孩子说出自己的希望。无论是正面的情绪还是负面的情绪，无论是好的行为还是坏的行为，情绪本身是没有对错之分，如果先入为主，认为孩子不可理喻，或者认为孩子不需要这种矫情的共情，那自己就带着某种色彩看孩子，自然就无法辨认孩子以及接纳和认可孩子。\u003c/p>","interaction":"\u003cp>现在这里分享我自己的一个案例，我们家孩子不喜欢在马桶上拉臭臭，有几次在孩子准备拉臭臭时候，专门跑去将孩子的小马桶拿过来，孩子推手说不要。我想让孩子养成自己在马桶拉臭臭的习惯，就各种哄，说蓝色的马桶多有趣啊之类的，孩子非常生气将马桶扔开，甚至还大吼走开。当时我想，这孩子咋这么倔……。现在细想一下，虽然当时没有做太多的强制干预，但当时，孩子是真实的，他就是不习惯用这马桶，这玩意他可能也没觉得多有趣，还影响他拉臭臭，而当时我只是一味表达孩子你应该喜欢这个马桶和使用这个马桶，并未认可孩子不喜欢马桶的这个感觉，就更没有了解背后原因相关语言沟通了。\u003c/p>\u003cp>基于原文提到的辨认和语言表达的两个关键步骤，针对孩子不喜欢在马桶拉臭臭的习惯，下次我会尝试以下步骤共情，1、辨认及试探孩子对在马桶拉臭的接受态度，2、引导孩子说出来自己情绪如：“你很不喜欢马桶是不是因为……？”3、引导孩子说出负面情绪的原因：“你在拉臭，不希望妈妈打搅你对吗？……”4、猜出或说出孩子的期望：“你是不是希望妈妈在你拉臭的时候不要打搅你……”5、日常上厕所让孩子看到，言传身教告诉孩子大人日常是怎么上厕所，激发孩子模仿大人马桶拉臭兴趣，6、引导孩子在马桶或厕所拉臭兴趣：我们现在来玩小熊和小猴在马桶拉臭的游戏吧……\u003c/p>\u003cp>接下来请各位伙伴想一个你在生活中经历过失败共情案例，在小组内作分享，时间是5分钟。\u003c/p>\u003cp>刚刚大家的讨论非常激烈，下面请一个小伙伴分享下自己关于共情的失败案例。\u003c/p>\u003cp>非常感谢楚榆分享的关于共情的失败案例，刚分享的时候比较激动，假设给你一次重来的机会你还会不会这么干？还会这么说么？相信你肯定不会这么说。\u003c/p>\u003cp>请各位伙伴根据刚分享的失败案例，应用片段提到的共情方法，下次将如何应用该知识点，并用便签写下来，建议有可操作的步骤，时间是1分钟。\u003c/p>\u003cp>下面我们来简单回顾下今天拆解的主题，共情包括两个过程，第一个过程是辨认孩子的感觉，包括正面感觉和负面感觉；第二个过程是准确地用语言表达出来。 今天大家都应用了这两个关键点去催化学习应用，非常感谢大家分享，谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1495260851000,"updated_at":1495260851000,"ria":true},{"id":2075,"topic":"共同解决问题的7个步骤","learn_goal":"共同解决问题的7个步骤","remark":"“正面管教”已成为美国主流家长教育体系之一。事实证明，家长们不但从“正面管教课堂”学到易学实用的方法，解决从孩子睡觉、拖拉、吃饭，不听指令、轻易放弃等日常问题，还帮助家长找到引导孩子自信，自律，拥有强大内心力量的成长途径。\r\n本书按照家长学习偏好，以11个深受中国家长欢迎的代表性工具入手，用家长真实案例来介绍正面管教方法和理念。工具式编排和案例式分享大幅降低家长接受正面管教的门槛。让正面管教可以帮助到更多家长。","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"饶晶晶","city":"上饶"},"club":{"name":"上饶三清山分舵","city":"上饶"},"prologue":"大家好，我是饶晶晶，乐观、开朗、充满正能量的新手拆书家。今天我训练的是《拆书家手册》V3的TF1-2，用How片段和大家一起学习，将便签法的R、I、A三个环节理解的更加透彻。接下来为我们今天的拆书活动做准备，我们需要分一下小组。（现场根据人数灵活分配）\r\n我今天带拆的图书是《行之有效的正面管教工具》，本书作者是甄颖，她是美国正面管教资质导师，也是育儿博主，育儿博客国内访问量最高达到3700万。《行之有效的正面管教工具》中通过实践在正面管教之路上宝妈们的真实育儿故事分享引导出正面管教中的十二个有效工具。有了这些工具家长们就如同有了法宝，可以轻而易举的拿下育儿途中的遭遇的各种“小怪兽”。在尊重自己和孩子的同时建立良好的沟通模式，找到最有效的解决问题的方法。","ratings_count":0,"texts":[{"id":4712,"quote":"\u003cp>共同解决问题的7个步骤\u003c/p>\u003cp>&nbsp; &nbsp;1.开始谈话。\u003c/p>\u003cp>&nbsp; &nbsp; 找个双方都情绪都平稳的时间和地点，和孩子坐下来：“我有件事想跟你谈谈，就是_______。我希望咱们能一起找到解决方法，你愿不愿意谈一谈？妈妈保证不发脾气，不生气。咱们都保证不互相指责？”——最后一句最重要，目的是为了保证谈话的情绪安全。\u003c/p>\u003cp>&nbsp; &nbsp;2.倾听孩子的想法。\u003c/p>\u003cp>&nbsp; &nbsp; 如果孩子不同意，告诉Ta：“好，我明白。等你想听的时候咱们再谈。”——不强迫，情绪安全。如果孩子同意，问；“你对这件事有什么想法？”你的感觉是什么？”听孩子说完后，用共情重复孩子的话。——让孩子先说，家长先听。倾听的同时，只需要共情即可，而不要点评，也不要着急给孩子讲道理。如果孩子说不出自己的感觉，家长可询问：“是不是觉得……”\u003c/p>\u003cp>3.说出自己的感受。\u003c/p>\u003cp>&nbsp; &nbsp; 听完孩子说完，问孩子：“你想不想听听妈妈的感觉是什么？”妈妈的感觉可能和你的不一样，这很正常，每个人的感觉都不一样。”然后，诚实的告诉孩子你的感觉。使用“我”句式。——告诉孩子“每个人感觉不一样，这很正常”，和第一步的最后一句同样重要。这一步不容易的地方，在于诚实地告诉孩子你的感觉，而不是你的道理。有家长到了这里就不由自主地将谈感觉变成了讲道理。谈感觉是谈心，讲道理则容易变成说教。\u003c/p>\u003cp>&nbsp; &nbsp; 4.感谢孩子。\u003c/p>\u003cp>&nbsp; &nbsp; 说完以后感谢孩子：“谢谢你听我说，也谢谢你告诉我你的感觉。”——这样的感谢虽然简单，但对于培养孩子和家长谈心的习惯，也就是前面3个步骤，非常有帮助。\u003c/p>\u003cp>&nbsp; &nbsp; 5.启发孩子解决问题的方法。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;问孩子：“你觉得你/我们能做些什么，来解决这个问题/困难？”或者使用启发式提问，听孩子说，或和孩子一起头脑风暴”。不批评、点评、否定孩子提出建议。可点头、微笑、“嗯”等表示听到了。——即使孩子的建议不可行，也写下来，以示对孩子的尊重。家长也可参与“头脑风暴”，目的是为了培养孩子独立思考的能力。如果孩子没有建议，家长也可自己提出建议。这时候，直接告诉孩子应该怎么做的“正面语言”，给孩子有限权力的“选择”，都可以使用。这时候，也可以适当给孩子讲道理，让孩子思路清晰理智。\u003c/p>\u003cp>&nbsp; &nbsp;6.选定解决方案。\u003c/p>\u003cp>&nbsp; &nbsp; 对于最可行和尊重双方的方式，最好由孩子自己选择。——孩子是当事人，自主选择为后面的执行打下良好的基础。\u003c/p>\u003cp>&nbsp; &nbsp; 7.约定回顾时间。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;约定一个时间来回顾、表达感激。——行大于言。前6步都是说，最后还是要落实在行为上。约定的时间不用太长，baby step，让孩子容易看到小进步，巩固执行效果，或者及时调整不当行为。\u003c/p>","explains":"\u003cp>&nbsp; 生活中当我们和孩子相处时会遇到许许多多的挑战，孩子做事拖拉，不按时睡觉，容易发脾气，喜欢玩手机或电脑游戏……虽然每个孩子给予的挑战不一样，但有意思的是这些挑战确实或多或少都存在于每个家庭。当面对这些形形色色的挑战时有些家长脸上写着大大的无奈，在要求孩子无果时只能做出让步，选择短暂性的逃避，本着眼不见为净的原则做出妥协。而有些家长则会火冒三丈，责骂呵斥Ta立即、马上将错误改正否则后果很严重。显而易见这两种方式对于解决问题都没有长期的效果可言。前者直接忽视孩子，后者将孩子处在一个感觉很糟糕的境地，它们都忽略了解决问题前需要先和孩子进行情感的连接。想要长期有效的解决问题需要做到以下几点：首先我们要制造一个情绪安全的氛围让孩子敢说，用心倾听孩子的感受，放下自己的指责埋怨，只是做一个忠实的听众。再诚实的说出自己的感觉，放弃长篇大论的说教，只是让孩子明白每个人都可以有自己的感受，感受可以不一样，感受没有对错之分。倾听和说出自己的感受可以让自己和孩子处于同频状态，让之后的良好沟通变得水到渠成。接下来真诚的感谢孩子的交谈，适当的时候给予拥抱和鼓励，这些小技巧是滋养亲子关系的必要养分。然后用启发式提问的方式培养孩子独立思考解决问题的能力，放开手让孩子自己思考，只是在旁边做一个引导者。最后选择一个经过Ta自己思考的可执行的方案落实并约定回顾时间巩固执行效果。整个过程都要以尊重孩子和尊重自己为前提，解决问题之前先连接情感。养育孩子的道路很漫长，但我们不能走得太着急，因为太着急我们就会忽略很多沿途的美景。放慢脚步，用心倾听孩子，现在的“慢”是为了以后轻松地走的得更远。\u003c/p>","interaction":"\u003cp>\u003cstrong>激活经验\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>现在请大家回想一下你们在平常和孩子或Ta人的相处过程中有没有急于想解决问题而忽略对方情感的例子？每组有五分钟组内互相分享时间，结束后邀请代表向大家分享一下自己的案例。\u003cbr>\u003c/p>\u003cp>学习者案列记录：\u003cbr>\u003c/p>\u003cp>&nbsp;四年级孩子小B总是不能按时完成作业，每天都拖拖拉拉，昨天晚上他又做到很晚，妈妈很愤怒“天天要做到这么晚，你动作就不能快一点吗？”孩子瞪了妈妈一眼“不用你管，你出去”。\u003c/p>\u003cp>\u003cstrong>\u003cstrong>【A2】\u003c/strong>催化应用\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>今天我们共同学习了解决问题的7个步骤，相信大家对每个步骤该说的话该做的动作都有了清晰的概念。现在请大家用一分钟的时间写下你将这7个步骤怎样应用到未来的生活中，注意我们写下的内容不是空想和决心，而是在明确的时间、地点、人物都有的场景中我们具体的做法。\u003cbr>\u003cstrong>学习者案例\u003c/strong>\u003cstrong>记录：\u003c/strong>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cb>时间：孩子晚间游戏之后\u003c/b>\u003c/p>\u003cp>\u003cb>地点：家里\u003c/b>\u003c/p>\u003cp>\u003cb>人物：妈妈和小B\u003c/b>\u003c/p>\u003cp>\u003cb>1\u003cstrong>.\u003c/strong>宝贝，妈妈有件事想跟你谈谈，就是关于你写作业的事。在谈话过程中妈妈保证不生气，你愿意和我谈谈吗？\u003c/b>\u003c/p>\u003cp>\u003cb>2.对于你每天不能按时完成作业，你的感受是怎么样的，能告诉我吗？\u003c/b>\u003c/p>\u003cp>\u003cb>3.妈妈的感受是很担心，担心你以后的学习会更加的辛苦。\u003c/b>\u003c/p>\u003cp>\u003cb>4.谢谢你可以心平气和的和妈妈聊这些。\u003c/b>\u003c/p>\u003cp>\u003cb>5.我们是不是可以一起共同想一些解决的方法呢？\u003c/b>\u003c/p>\u003cp>\u003cb>6.那我们就暂时选定A方案。\u003c/b>\u003c/p>\u003cp>\u003cb>7.一个星期以后看它是否有效果，再决定是否继续使用。\u003c/b>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1488531965000,"updated_at":1488531999000,"ria":true},{"id":2074,"topic":"提前说","learn_goal":"提前说","remark":"“正面管教”已成为美国主流家长教育体系之一。事实证明，家长们不但从“正面管教课堂”学到易学实用的方法，解决从孩子睡觉、拖拉、吃饭，不听指令、轻易放弃等日常问题，还帮助家长找到引导孩子自信，自律，拥有强大内心力量的成长途径。\r\n本书按照家长学习偏好，以11个深受中国家长欢迎的代表性工具入手，用家长真实案例来介绍正面管教方法和理念。工具式编排和案例式分享大幅降低家长接受正面管教的门槛。让正面管教可以帮助到更多家长。","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"饶晶晶","city":"上饶"},"club":{"name":"上饶三清山分舵","city":"上饶"},"prologue":"一、自我介绍（1分钟）\r\n 大家好，我是饶晶晶，下面我想用三个标签简单的介绍一下自己。1.我是四周岁女孩徐怡霏的妈妈，有人说女子本弱、为母则刚，感谢女儿让我变得更加有力量，有了她以后我想要成为更好的那个自己。2.教师，我在广丰区特殊教育学校教聋哑的孩子，感谢这群折翼的天使让我更懂得了爱和感恩3.自由创业者，除了教书我自己还开了一家琴行和一家幼儿园，感谢学生和家长们对我的信任，让我可以一直带着这一份力量前行，希望不久的将来我还能加上一个标签,那就是成为拆书帮的三级拆书家。感谢大家今天能在百忙之中抽空参加这个活动，陪伴我一同朝目标迈进一步。\r\n二、拆书帮介绍（2分钟）\r\n “拆书”是一种学习方法，“拆”不是“拆散”而是转化和内化。强调把图书的知识拆页转化为学习者的能力。成人可以通过拆书提升能力，解决问题。强调以学习者为中心，而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。 \r\n 拆书法分为应用于个人学习的拆书帮便签法和应用于组织学习的拆书帮现场学习法。其中个人便签发包括R、I、A三个环节，R是指阅读原文拆页，I环","ratings_count":0,"texts":[{"id":4711,"quote":"\u003cp>&nbsp; “提前说”，看似很小，可起到的作用非常大。用具体而清晰的语言，提前告诉孩子接下来要做什么，会给孩子带来很大的安全感！\u003c/p>\u003cp>&nbsp; &nbsp;否则，孩子的事情都有大人安排，虽然大人心里很清楚接下来要做什么，但不告诉孩子，那么孩子的心中依然一片茫然，惶惑。再加上被动地遵从，是最容易发生矛盾的时刻之一。\u003c/p>\u003cp>&nbsp; &nbsp;“提前说”几乎可以用于一切场合。另一位从“正面管教妈妈”成长起来的“正面管教讲师”梁良，曾很惊喜地分享过她对1岁2个月儿子“提前说”的效果：以前一到要下楼的时间，我儿子就急，稍微慢一点他就哭，就闹。后来，快到时间的时候，我提前告诉他：“等一下妈妈要先去洗手间，然后把你的东西准备好，然后给你穿外套，穿鞋，然后妈妈穿鞋。然后我们就一起下楼玩了。”虽然我儿子才一岁，可是竟然都明白，耐心地等我做完这些事，不再哭闹了！\u003c/p>\u003cp>&nbsp; &nbsp;“提前说”就是给孩子机会，让孩子对未来做好准备。所以，提前说的语言越详细越具体越好。\u003c/p>","explains":"\u003cp>人有时候会害怕，是因为不知道接下来会发生什么事情。未知事件通常多数人感到恐惧的原因。特别是小孩子，当你把Ta突然放到一个陌生的环境面对陌生的人群，Ta会很没有安全感。不知道接下来该做什么，更没有信心相信自己能够做好。孩子缺乏安全感时通常的表现是哭闹或想要逃离。如果家长提前用清晰的语言详细具体的告诉Ta接下来会遇见什么事情和该做些什么可以避免感到不知所措而引发一系列的负面情绪。“提前说”可以将问题终止在萌芽期，让亲子沟通变得更顺畅。\u003c/p>","interaction":"\u003cp>A1\u003c/p>\u003cp>女儿三周岁时每次午睡或早晨睡醒后看身旁没人就大哭不止。有时我正专心做一件事情一听到她撕心裂肺的哭声就得急忙跑进房间。接下来是一阵安慰。这样的场景每天都上演却又无力改变。看着眼前这个哭的很伤心的小家伙心里的感觉是烦躁而又无奈。后来我尝试用“提前说”，睡觉前我告诉她：“宝贝，妈妈可能会醒的比你早一些，如果你醒来后没看见妈妈就大声叫一下我好吗？那样我就可以马上“飞”到你身边。或者你也可以自己穿上鞋子出来找妈妈，然后偷偷站在妈妈身后吓我一大跳”。女儿听完后爽快的答应了。第二天早晨我正在厨房准备早餐，她醒来后没有哭闹而是自己下床穿上鞋子走到我身后吓我一跳。我抱了抱她，愉快的一天从就这样开始了。更神奇的是从那天以后起床看不见人哭闹的现象再也没有发生过。可见“提前说”可以给予孩子强大的安全感。\u003c/p>\u003cp>A2\u003c/p>\u003cp>马上就过年了，避免不了正月里需要到亲戚家拜年，对于孩子来说每天更换一个吃饭的地点未必是一件容易接受的事，为了让她能很快的适应每天的行程我需要预设场景如下：\u003c/p>\u003cp>时间：正月某一天的晚上\u003c/p>\u003cp>地点：小宝的家\u003c/p>\u003cp>人物：妈妈、小宝\u003c/p>\u003cp>对话\u003c/p>\u003cp>妈妈：小宝，明天上午我们需要去小姑婆家拜年，到时候会很热闹，你会看见很多叔叔阿姨，哥哥姐姐。中午会在她家里吃午餐，下午你可以和她们家的哥哥姐姐们一起玩，我、爸爸和你一起吃完晚饭再回来。\u003c/p>\u003cp>小宝：知道的\u003c/p>\u003cp>（2）将“提前说”应用到日常惯例表的活动实施中\u003c/p>\u003cp>例如：“小宝，再过五分钟动画片时间就结束了，我们接下来需要做的是洗漱然后上床睡觉”。提前说可以让孩子有心理准备，不会对接下来要做的事情报以抵触的心理。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1488530435000,"updated_at":1497006342000,"ria":true}]};